comms.text:
@1 וַהֲוָה מִסּוֹף תַּרְתֵּין שְׁנִין וּפַרְעֹה חָלֵם וְהָא קָאֵם עַל נַהֲרָא:
@2 וְהָא מִן נַהֲרָא סָלְקָן שְׁבַע תּוֹרָן שַׁפִּירָן לְמֶחֱזֵי וּפַטִּימָן בְּשָׂר וְרָעְיָן בְּאַחְוָה:
@3 וְהָא שְׁבַע תּוֹרָן אָחֳרָנְיָן סָלְקָן בַּתְרֵיהוֹן מִן נַהֲרָא בִּישָׁן לְמֶחֱזֵי וַחֲסִירַן בְּשָׂר וְקָמָן לְקִבְלֵיהוֹן דְּתוֹרָן עַל כֵּיף נַהֲרָא:
@4 וַאֲכָלַן תּוֹרְתָּא בִּישָׁן לְמֶחֱזֵי וַחֲסִירַן בְּשַׂר יָת שְׁבַע תּוֹרְתָּא שַׁפִּירָן לְמֶחֱזֵי וּפַטִּימָתָא וְאִתְּעַר פַּרְעֹה:
@5 וּדְמוּךְ וַחֲלַם תִּנְיָנוּת וְהָא שְׁבַע שֻׁבְּלַיָּא סָלְקָן בְּקַנְיָא חַד פַּטִּימָן וְטָבָן:
@6 וְהָא שְׁבַע שֻׁבְּלַיָּא לָקְיָן וּשְׁקִיפָן קִדּוּם צָמְחָן בַּ:תרֵיהוֹן:
@7 וּבְלָעָא שֻׁבְּלַיָּא לָקְיָתָא יָת שְׁבַע שֻׁבְּלַיָּא פַּטִּימָתָא וּמָלְיָתָא וְאִתְּעַר פַּרְעֹה וְהָא חֶלְמָא:
@8 וַהֲוָה בְצַפְרָא וּמִטַּרְפָּא רוּחֵהּ וּשְׁלַח וּקְרָא יָת כָּל חֳרָשֵׁי מִצְרַיִם וְיָת כָּל חַכִּימָהָא וְאִשְׁתָּעִי פַרְעֹה לְהוֹן יָת חֶלְמֵהּ וְלֵית דְּפָשַׁר יָתְהוֹן לְפַרְעֹה:
@9 וּמַלִּיל רַב שָׁקֵי (עִם פַּרְעֹה) לְפַרְעֹה לְמֵימָר יָת סָרְחָנִי אֲנָא מַדְכַּר יוֹמָא דֵּין:
@10 פַּרְעֹה רְגֵז עַל עַבְדוֹהִי וִיהַב יָתִי בְּמַטְּרָא בֵּית רַב קָטוֹלַיָּא יָתִי וְיָת רַב נַחְתּוֹמֵי:
@11 וַחֲלֵמְנָא חֶלְמָא בְּלֵילְיָא חַד אֲנָא וָהוּא גְּבַר כְּפִשְׁרַן חֶלְמֵהּ חֲלֵמְנָא:
@12 וְתַמָּן עִמָּנָא עוּלֵם עִבְרָאָה עַבְדָא לְרַב קָטוֹלַיָּא וְאִשְׁתָּעֵינָא לֵהּ וּפָשַׁר לָנָא יָת חֶלְמָנָא גְּבַר כְּחֶלְמֵהּ פָּשָׁר:
@13 וַהֲוָה כְּמָא דִּי פָשַׁר לָנָא כֵּן הֲוָה יָתִי אֲתֵיב עַל שִׁמּוּשִׁי וְיָתֵהּ צְלָב:
@14 וּשְׁלַח פַּרְעֹה וּקְרָא יָת יוֹסֵף וְאַרְהָטוּהִי מִן בֵּית אֲסִירֵי וְסַפַּר וְשַׁנִּי כְסוּתֵהּ וְעַל לְוַת פַּרְעֹה:
@15 וַאֲמַר פַּרְעֹה לְיוֹסֵף חֶלְמָא חֲלֵמִית וּפָשַׁר לֵית לֵהּ וַאֲנָא שִׁמְעֵית עֲלָךְ לְמֵימַר דְּאַתְּ שָׁמַע חֶלְמָא לְמִפְשַׁר יָתֵהּ:
@16 וַאֲתֵיב יוֹסֵף יָת פַּרְעֹה לְמֵימַר בַּר מִן חָכְמְתִי אֶלָּהֵן מִן קֳדָם יְיָ יִתֹּתַב יָת שְׁלָמָא דְפַרְעֹה:
@17 וּמַלֵּיל פַּרְעֹה עִם יוֹסֵף בְּחֶלְמִי הָא אֲנָא קָאֵם עַל כֵּיף נַהֲרָא:
@18 וְהָא מִן נַהֲרָא סָלְקָן שְׁבַע תּוֹרָן פַּטִּימָן בְּשַׂר וְשַׁפִּירָן לְמֶחֱזֵי וְרַעְיָן בְּאַחֲוָה:
@19 וְהָא שְׁבַע תּוֹרָן אָחֳרָנְיָן סָלְקָן בַּתְרֵיהוֹן חֲסִיכָן וּבִישָׁן לְמֶחֱזֵי לַחֲדָא וַחֲסִירָן בְּשָׂר לָא חֲזֵתִי כְוָתְהֵן בְּכָל אַרְעָא דְמִצְרַיִם לְבִישׁוּ:
@20 וַאֲכָלָן תּוֹרְתָּא חֲסִיכָתָא וּבִישָׁתָא יָת שְׁבַע תּוֹרְתָּא קַדְמָיָתָּא פַּטִּימָתָא:
@21 וַעֲלָא לִמְעֵיהֶן וְלָא אִתְיְדַע אֲרֵי עַלּוּ לִמְעֵיהֶן וּמֶחֱזֵיהֶן בִּישׁ כַּד בְּקַדְמֵיתָא וְאִתְּעָרִית:
@22 וַחֲזֵית בְּחֶלְמִי וְהָא שְׁבַע שֻׁבְּלַיָּא סָלְקָן בְּקַנְיָא חַד מָלְיָן וְטָבָן:
@23 וְהָא שְׁבַע שֻׁבְּלַיָּא נָצָן לָקְיָן שְׁקִיפָן קִדּוּם צָמְחָן בַּתְרֵיהוֹן:
@24 וּבְלָעָן שֻׁבְּלַיָּא לָקְיָתָא יָת שְׁבַע שֻׁבְּלַיָּא טָּבָתָא וַאֲמָרִית לַחֲרָשַׁיָּא וְלֵית דִּי מְחַוֵּי לִי:
@25 וַאֲמַר יוֹסֵף לְפַרְעֹה חֶלְמָא דְפַּרְעֹה חַד הוּא יָת דִּי יְיָ עָתִיד לְמֶעְבַּד חַוִּי לְפַרְעֹה:
@26 שְׁבַע תּוֹרְתָּא טָבָתָא שְׁבַע שְׁנִין אִנּוּן וּשְׁבַע שֻׁבְּלַיָּא טָבָתָא שְׁבַע שְׁנִין אִנּוּן חֶלְמָא חַד הוּא:
@27 וּשְׁבַע תּוֹרְתָּא חֲסִיכָתָא וּבִישָׁתָא דְסָלְקָן בַּתְרֵיהוֹן שְׁבַע שְׁנִין אִנּוּן וּשְׁבַע שֻׁבְּלַיָּא לָקְיָתָא דִּשְׁקִיפָן קִדּוּם יְהֶוְיָן שְׁבַע שְׁנֵי כַפְנָא:
@28 הוּא פִתְגָּמָא דִּי מַלֵּילִית עִם פַּרְעֹה דִּי יְיָ עָתִיד לְמֶעְבַּד אַחֲזֵי לְפַרְעֹה:
@29 הָא שְׁבַע שְׁנִין אָתְיָן שׂוֹבְעָא רַבָּא בְּכָל אַרְעָא דְמִצְרָיִם:
@30 וִיקוּמוּן שְׁבַע שְׁנֵי כַפְנָא בַּתְרֵיהֶן וְיִתִנְשֵׁי כָּל שׂוֹבְעָא בְּאַרְעָא דְמִצְרָיִם וִישֵׁיצֵי כַפְנָא יָת (עַמָּא דְ) אַרְעָא:
@31 וְלָא יִתְיְדַע שׂוֹבְעָא בְּאַרְעָא מִן קֳדָם כַּפְנָא הַהוּא דִּיהֵי בָתַר כֵּן אֲרֵי תַקִּיף הוּא לַחֲדָא:
@32 וְעַל דְּאִתַּנֵּית חֶלְמָא לְפַרְעֹה תַּרְתֵּין זִמְנִין אֲרֵי תַקִּין פִּתְגָּמָא מִן קֳדָם יְיָ וְאוֹחִי יְיָ לְמֶעְבְּדֵהּ:
@33 וּכְעַן יֶחֱזֵי פַרְעֹה גְּבַר סוּכְלְתָן וְחַכִּים וִימַנִינֵיהּ עַל אַרְעָא דְמִצְרָיִם:
@34 יַעְבֵּד פַרְעֹה וִימַנֵּי מְהֵימְנִין עַל אַרְעָא וִיזָרֵז יָת אַרְעָא דְמִצְרַיִם בְּשֶׁבַע שְׁנֵי שׂוֹבְעָא:
@35 וְיִכְנְשׁוּן יָת כָּל עִיבוּר שְׁנַיָּא טָבָן דְּאָתְיָן הָאִלֵּין וְיִצְבְּרוּן עִיבוּרָא תְּחוֹת יְדָא מְהֵימְנֵי דְפַרְעֹה עִיבוּרָא בְּקִירְוַיָּא וְיִטְּרוּן:
@36 וִיהֵי עִיבוּרָא גְּנִיז (לְעַמָּא דְ) לְאַרְעָא לִשְׁבַע שְׁנֵי כַפְנָא דִּי תְהֶוְיָן בְּאַרְעָא דְמִצְרָיִם וְלָא תִשְׁתֵּיצֵי עַמָּא דְאַרְעָא בְּכַפְנָא:
@37 וּשְׁפַר פִּתְגָּמָא בְּעֵינֵי פַרְעֹה וּבְעֵינֵי כָּל עַבְדּוֹהִי:
@38 וַאֲמַר פַּרְעֹה לְעַבְדוֹהִי הֲנִשְׁכַּח כְּדֵין גְּבַר דִּי רוּחַ נְבוּאָה מִן קֳדָם יְיָ בֵּהּ:
@39 וַאֲמַר פַּרְעֹה לְיוֹסֵף בָּתַר דְּאוֹדַע יְיָ יָתָךְ יָת כָּל דָּא לֵית סָכְלְתָן וְחַכִּים כְּוָתָךְ:
@40 אַתְּ תְּהֵי מְמַנָּא עַל בֵּיתִי וְעַל מֵימְרָךְ יִתְּזַן כָּל עַמִּי לְחוֹד כָּרְסֵי מַלְכוּתָא הָדֵין אֵיהֵי יַקִּיר מִנָּךְ:
@41 וַאֲמַר פַּרְעֹה לְיוֹסֵף חֲזֵי מַנֵּיתִי יָתָךְ עַל כָּל אַרְעָא:דמִצְרָיִם:
@42 וְאַעְדִּי פַרְעֹה יָת עִזְקְתֵהּ מֵעַל יְדֵהּ וִיהַב יָתַהּ עַל יְדָא דְיוֹסֵף וְאַלְבִּישׁ יָתֵהּ לְבוּשִׁין דְּבוּץ וְשַׁוִּי מָנִיכָא דְדַהֲבָא עַל צַוְּארֵהּ:
@43 וְאַרְכֵּיב יָתֵהּ בִּרְתִכָּא תִנְיֵתָא (נ''י תִנְיָנָא) דִּי לֵהּ וְאַכְרִיזוּ קֳדָמוֹהִי דֵּין אַבָּא לְמַלְכָּא וּמַנִּי יָתֵהּ עַל כָּל אַרְעָא דְמִצְרָיִם:
@44 וַאֲמַר פַּרְעֹה לְיוֹסֵף אֲנָא פַרְעֹה וּבַר מֵימְרָךְ לָא יְרִים גְּבַר יָת יְדֵהּ לְמֵיחַד זֵין וְיָת רִגְלֵהּ לְמִרְכַּב עַל סוּסְיָא בְּכָל אַרְעָא דְמִצְרָיִם:
@45 וּקְרָא פַּרְעֹה שׁוּם יוֹסֵף גַּבְרָא דְמִטַּמְרָן גָּלְיָן לֵהּ וִיהַב לֵהּ יָת אָסְנַת בַּת פּוֹטִי פֶרַע רַבָּא דְאוֹן לְאִתְּתָא וּנְפַק יוֹסֵף (שַׁלִּיט) עַל אַרְעָא דְמִצְרָיִם:
@46 וְיוֹסֵף בַּר תְּלָתִין שְׁנִין כַּד קָם קֳדָם פַּרְעֹה מַלְכָּא דְמִצְרָיִם וּנְפַק יוֹסֵף מִן קֳדָם פַּרְעֹה וַעֲבַר (שַׁלִּיט) בְּכָל אַרְעָא דְמִצְרָיִם:
@47 וּכְנָשׁוּ דָיְרֵי אַרְעָא בִּשְׁבַע שְׁנֵי שׂוֹבְעָא עִיבוּרָא לְאוֹצָרִין:
@48 וּכְנַשׁ יָת כָּל עִיבוּר שְׁבַע שְׁנִין דִּי הֲווֹ בְּאַרְעָא דְמִצְרַיִם וִיהַב עִיבוּר בְּקִרְוַיָּא עִיבוּר חֲקַל קַרְתָּא דִּי בְסַחְרָנָהָא יְהַב בְּגַוָּהּ:
@49 וּכְנַשׁ יוֹסֵף עִיבוּרָא כְּחַלָּא דְיַמָּא סַגִּי לַחֲדָא עַד דִּי פְסַק לְמִמְנֵי אֲרֵי לֵית מִנְיָן:
@50 וּלְיוֹסֵף אִתְיְלִיד תַּרְתֵּין בְּנִין עַד לָא עַלַּת שַׁתָּא דְכַפְנָא דִּילִידַת לֵהּ אָסְנַת בַּת פּוֹטִי פֶרַע רַבָּא דְאוֹן:
@51 וּקְרָא יוֹסֵף יָת שׁוּם בּוּכְרָא מְנַשֶּׁה אֲרֵי אַנְשְׁיַנִי יְיָ יָת כָּל עַמְלִי וְיָת כָּל בֵּית אַבָּא:
@52 וְיָת שׁוּם תִּנְיָנָא קְרָא אֶפְרָיִם אֲרֵי אַפְשַׁנִּי יְיָ בְּאַרַע שִׁעְבּוּדִי:
@53 וּשְׁלִימַת שְׁבַע שְׁנֵי שׂוֹבְעָא דִּי הֲוָה בְּאַרְעָא דְמִצְרָיִם:
@54 וּשְׁרִיאַת שְׁבַע שְׁנֵי כַפְנָא לְמֵיעַל כְּמָא דִּי אֲמַר יוֹסֵף וַהֲוָה כַפְנָא בְּכָל אַרְעֲתָא וּבְכָל אַרְעָא דְמִצְרַיִם הֲוָה לַחְמָא:
@55 וּכְפָנַת כָּל אַרְעָא דְמִצְרַיִם וּצְוַח עַמָּא קֳדָם לְפַרְעֹה עַל לַחְמָא וַאֲמַר פַּרְעֹה לְכָל מִצְרָאֵי אִיזִילוּ לְוַת יוֹסֵף דִּי יֵימַר לְכוֹן תַּעְבְּדוּן:
@56 וְכַפְנָא הֲוָה עַל כָּל אַפֵּי אַרְעָא וּפְתַח יוֹסֵף יָת כָּל דִּי בְהוֹן עִיבוּרָא וְזַבִּין לְמִצְרַיִם וּתְקֵיף כַּפְנָא בְּאַרְעָא דְמִצְרָיִם:
@57 וְכָל דָּיְרֵי אַרְעָא עַלּוּ לְמִצְרַיִם לְמִזְבַּן עִיבוּרָא מִן יוֹסֵף אֲרֵי תְקֵיף כַּפְנָא בְּכָל אַרְעָא:
@58 וַחֲזָא יַעֲקֹב אֲרֵי אִית עִיבוּרָא מִזְדַּבַּן בְּמִצְרָיִם וַאֲמַר יַעֲקֹב לִבְנוֹהִי לְמָא תִּתְחֲזוּן:
@59 וַאֲמַר הָא שְׁמָעִית אָמְרִין אֲרֵי אִית עִיבוּרָא מִזְדַּבַּן בְּמִצְרָיִם חוּתוּ תַמָּן וּזְבוּנוּ לָנָא מִּתַּמָּן וְנֵחֵי וְלָא נְמוּת:
@60 וּנְחָתוּ אֲחֵי יוֹסֵף עַסְרָא לְמִזְבַּן עִיבוּרָא מִמִּצְרָיִם:
@61 וְיָת בִּנְיָמִין אֲחוּהִי דְיוֹסֵף לָא שְׁלַח יַעֲקֹב עִם אֲחוֹהִי אֲרֵי אֲמַר דִּלְמָא יְעַרְעִנֵּהּ מוֹתָא:
@62 וַאֲתוֹ בְּנֵי יִשְׂרָאֵל לְמִזְבַּן עִיבוּרָא בְּגוֹ עָלַיָּא אֲרֵי הֲוָה כַפְנָא בְּאַרְעָא דִּכְנָעַן:
@63 וְיוֹסֵף הוּא דְּשַׁלִּיט עַל אַרְעָא הוּא דְזַבִּין עִיבוּרָא לְכָל עַמָּא דְאַרְעָא וַאֲתוֹ אֲחֵי יוֹסֵף וּסְגִידוּ לֵהּ עַל אַפֵּיהוֹן עַל אַרְעָא:
@64 וַחֲזָא יוֹסֵף יָת אֲחוֹהִי וְאִשְׁתְּמוֹדְעִנּוּן וְחַשִּׁיב מָה דְמַלֵּיל לְהוֹן וּמַלִּיל עִמְּהוֹן קַשְׁיָן וַאֲמַר לְהוֹן מְנָן אֲתֵיתוּן וַאֲמָרוּ מֵאַרְעָא דִּכְנַעַן לְמִזְבַּן עִיבוּרָא:
@65 וְאִשְׁתְּמוֹדַע יוֹסֵף יָת אֲחוֹהִי וְאִנּוּן לָא אִשְׁתְּמוֹדְעוֹהִי:
@66 וּדְכִיר יוֹסֵף יָת חֶלְמַיָּא דִּי חֲלִים לְהוֹן וַאֲמַר לְהוֹן מְאַלְלִין אַתּוּן לְמֶחֱזֵי יָת בִּדְקָא דְאַרְעָא אֲתֵיתוּן:
@67 וַאֲמָרוּ לֵהּ לָא רִבּוֹנִי וְעַבְדָּיךְ עַלּוּ לְמִזְבַּן עִיבוּרָא:
@68 כֻּלָּנָא בְּנֵי גַּבְרָא חַד נָחְנָא כֵּיוָנֵי אֲנַחְנָא לָא הֲווֹ עַבְדָיךְ אַלִּילֵי:
@69 וַאֲמַר לְהוֹן לָא אֲרֵי בִדְקָא דְאַרְעָא אֲתֵיתוּן לְמֶחֱזֵי:
@70 וַאֲמָרוּ תְּרֵין עֲשַׂר עַבְדָיךְ אַחִין אֲנַחְנָא בְּנֵי גַּבְרָא חַד בְּאַרְעָא דִּכְנָעַן וְהָא זְעֵירָא עִם אָבוּנָא יוֹמָא דֵּין וְחַד לֵיתוֹהִי:
@71 וַאֲמַר לְהוֹן יוֹסֵף הוּא דִּי מַלֵּילִית עִמְּכוֹן לְמֵימַר אַלִּילֵי אַתּוּן:
@72 בְּדָא תִּתְבַּחֲרוּן חֵי פַרְעֹה אִם תִּפְקוּן מִכָּא אֶלָּהֵין בְּמֵתֵי אֲחוּכוֹן זְעֵירָא הָכָא:
@73 שְׁלָחוּ מִנְּכוֹן חַד וְיִדְבַּר יָת אֲחוּכוֹן וְאַתּוּן תִּתְאַסְרוּן וְיִתְבַּחֲרוּן פִּתְגָּמֵיכוֹן הַקְּשׁוֹטּ אַתּוּן אָמְרִין וְאִם לָא חֵי פַרְעֹה אֲרֵי אַלִּילֵי אַתּוּן:
@74 וּכְנַשׁ יָתְהוֹן לְבֵית מַטְרָא תְּלָתָא יוֹמִין:
@75 וַאֲמַר לְהוֹן יוֹסֵף בְּיוֹמָא תְלִיתָאָה דָּא עִבִידוּ וְאִתְקַיָּמוּ מִן קֳדָם יְיָ אֲנָא דָּחֵל:
@76 אִם כֵּיוָנֵי אַתּוּן אֲחוּכוֹן חַד יִתְאַסַּר בְּבֵית מַטַּרְתְּכוֹן וְאַתּוּן אִיזִילוּ אוֹבִילוּ עִיבוּרָא דְּחַסִּיר בְּבָתֵּיכוֹן:
@77 וְיָת אֲחוּכוֹן זְעֵירָא תַּיְתוּן לְוָתִי וְיִתְהֵמְנוּן פִּתְגָּמֵיכוֹן וְלָא תְמוּתוּן וַעֲבָדוּ כֵן:
@78 וַאֲמָרוּ גְּבַר לַאֲחוּהִי בְּקוּשְׁטָּא חַיָּבִין אֲנַחְנָא עַל אָחוּנָא דִּי חֲזֵינָא עָקַת נַפְשֵׁהּ כַּד הֲוָה מִתְחַנֶּן לָנָא וְלָא קַבֵּלְנָא מִנֵּהּ עַל כֵּן אָתַת לְוָתָנָא עַקְתָא הָדָא:
@79 וַאֲתֵיב רְאוּבֵן יָתְהוֹן לְמֵימָר הֲלָא אֲמָרִית לְוָתְכוֹן לְמֵימַר לָא תְחוֹבוּן בְּעוּלֵימָא וְלָא קַבֶּלְתּוּן וְאַף דְּמֵהּ הָא מִתְבְּעֵי:
@80 וְאִנּוּן לָא יָדְעוּן אֲרֵי שְׁמִיעַ יוֹסֵף אֲרֵי מְתֻרְגְּמָן הֲוָה בֵינֵיהוֹן:
@81 וְאִסְתַּחַר מֵעִלָּוֵיהוֹן וּבְכָא וְתָב לְוָתְהוֹן וּמַלֵּיל עִמְּהוֹן וּדְבַר מִלְּוַתְהוֹן יָת שִׁמְעוֹן וַאֲסַר יָתֵהּ לְעֵינֵיהוֹן:
@82 וּפַקֵּיד יוֹסֵף וּמְלוֹ יָת מָנֵיהוֹן עִיבוּרָא וְלַאֲתָבָא כַסְפֵּיהוֹן גְּבַר לְסַקֵּהּ וּלְמִתַּן לְהוֹן זְוָדִין לְאָרְחָא וַעֲבַד לְהוֹן כֵּן:
@83 וּנְטָלוּ יָת עִיבוּרְהוֹן עַל חֲמָרֵיהוֹן וַאֲזָלוּ מִתַּמָּן:
@84 וּפְתַח חַד יָת סַקֵּהּ לְמִתַּן כִּסְתָא לַחֲמָרֵהּ בְּבֵית מְבָתָא וַחֲזָא יָת כַּסְפֵּהּ וְהָא הוּא בְּפוּם טוֹעֲנֵהּ:
@85 וַאֲמַר לַאֲחוֹהִי אִתּוֹתַב כַּסְפִּי וְאַף הָא בְטּוֹעֲנִי וּנְפַק מַדַּע לִבְּהוֹן וּתְוָהוּ גְּבַר לַאֲחוּהִי לְמֵימַר מָה דָּא עֲבַד יְיָ לָנָא:
@86 וַאֲתוֹ לְוַת יַעֲקֹב אֲבוּהוֹן אַרְעָא דִּכְנָעַן וְחַוִּיוּ לֵהּ יָת כָּל דְעַרְעָא יָתְהוֹן לְמֵימָר:
@87 מַלֵּיל גַּבְרָא רִבּוֹנָא דְאַרְעָא עִמָּנָא קַשְׁיָן וִיהַב יָתָנָא כִּמְאַלִּילֵי יָת אַרְעָא:
@88 וַאֲמַרְנָא לֵהּ כֵּיוָנֵי אֲנָחְנָא לָא הֲוֵינָא אַלִּילֵי:
@89 תְּרֵין עֲסַר אֲנַחְנָא אַחִין בְּנֵי אָבוּנָא חַד לֵיתוֹהִי וּזְעֵירָא יוֹמָא דֵּין עִם אָבוּנָא בְּאַרְעָא דִּכְנָעַן:
@90 וַאֲמַר לָנָא גַּבְרָא רִבּוֹנָא דְּאַרְעָא בְּדָא אִדַּע אֲרֵי כֵיוָנֵי אַתּוּן אֲחוּכוֹן חַד שְׁבוּקוּ לְוָתִי וְיָת עִיבוּרָא דְחַסִּיר בְּבָתֵּיכוֹן סִיבוּ וֶאֱזִילוּ:
@91 וְאַיְתִיאוּ יָת אֲחוּכוֹן זְעֵירָא לְוָתִי וְאִדַּע אֲרֵי לָא אַלִּילֵי אַתּוּן אֲרֵי כֵיוָנֵי אַתּוּן יָת אֲחוּכוֹן אֶתֵּן לְכוֹן וְיָת אַרְעָא תַּעְבְּדוּן בַּהּ סְחוֹרְתָּא:
@92 וַהֲוָה אִנּוּן מְרִיקִין סַקֵּיהוֹן וְהָא גְּבַר צְרִיר כַּסְפֵּהּ בְּסַקֵּהּ וַחֲזוֹ יָת צְרָרֵי כַסְפֵּיהוֹן אִנּוּן וַאֲבוּהוֹן וּדְחִילוּ:
@93 וַאֲמַר לְהוֹן יַעֲקֹב אֲבוּהוֹן יָתִי אַתְכֶּלְתּוּן יוֹסֵף לֵיתוֹהִי וְשִׁמְעוֹן לָא הֲוָה הָכָא (לֵיתוֹהִי) וְיָת בִּנְיָמִן תִּדְבְּרוּן עֲלַי הֲווֹ כָלְּהוֹן:
@94 וַאֲמַר רְאוּבֵן לְוַת אֲבוּהִי לְמֵימַר יָת תְּרֵין בְּנַי תְּמִית אִם לָא אַיְתִנֵּהּ לְוָתָךְ הַב יָתֵהּ עַל יְדִי וַאֲנָא אֲתֵבִנֵּהּ לָךְ:
@95 וַאֲמַר לָא יֵחוּת בְּרִי עִמְּכוֹן אֲרֵי אָחוּהִי מִית וְהוּא בִּלְחוֹדוֹהִי אִשְׁתָּאַר וִיעַרְעִנֵּהּ מוֹתָא בְּאָרְחָא דִּי תְהָכוּן בַּהּ וְתַחֲתוּן יָת שִׂיבְתִי בְּדָווֹנָא לִשְׁאוֹל:
@96 וְכַפְנָא תַּקִּיף בְּאַרְעָא:
@97 וַהֲוָה כַּד שֵׁיצִיאוּ לְמֵיכַל יָת עִיבוּרָא דְּאַיְתִיאוּ מִמִּצְרָיִם וַאֲמַר לְהוֹן אֲבוּהוֹן תּוּבוּ זְבוּנוּ לָנָא זעֵיר עִיבוּרָא:
@98 וַאֲמַר לֵהּ:יְהוּדָה לְמֵימָר אַסְהָדָא אַסְהֵד בָּנָא גַּבְרָא לְמֵימָר לָא תֶחֱזוּן אַפַּי אֶלָּהֵין כַּד אָחוּכוֹן עִמְּכוֹן:
@99 אִם אִיתָךְ מְשַׁלַּח יָת אָחוּנָא עִמָּנָא נֵיחוֹת וְנִזְבֵּן לָךְ עִיבוּרָא:
@100 וְאִם לֵיתָךְ מְשַׁלַּח לָא נֵיחוֹת אֲרֵי גַּבְרָא אֲמַר לָנָא לָא תֶחֱזוּן אַפַּי אֶלָּהֵין כַּד אֲחוּכוֹן עִמְּכוֹן:
@101 וַאֲמַר יִשְׂרָאֵל לְמָה אַבְאֶשְׁתּוּן לִי לְחַוָּאָה לְגַבְרָא הַעַד כְּעַן לְכוֹן אָחָא:
@102 וַאֲמָרוּ מִשְׁאַל שָׁאֵל גַּבְרָא לָנָא וּלְיַלָּדוּתָנָא לְמֵימַר הַעַד כְּעַן אֲבוּכוֹן קַיָּם הַאִית לְכוֹן אָחָא וְחַוֵּינָא לֵהּ עַל מֵימַר פִּתְגָּמַיָּא הָאִלֵּין הֲמִדַּע הֲוֵינָא יָדְעִין אֲרֵי יֵימַר אוֹחִיתוּ יָת אֲחוּכוֹן:
@103 וַאֲמַר יְהוּדָה לְיִשְׂרָאֵל אֲבוּהִי שְׁלַח עוּלֵימָא עִמִּי וְנֵקוּם וְנֵזֵיל וְנֵיחֵי וְלָא נְמוּת אַף אֲנַחְנָא אַף אַתְּ אַף טַפְלָנָא:
@104 אֲנָא מְעָרַבְנָא בֵהּ מִן יְדִי תִּבְעִנֵּהּ אִם לָא אַיְתִנֵּהּ לָךְ וַאֲקֵימִנֵּהּ קֳדָמָךְ וְאֵהֵי חָטֵי לָךְ כָּל יוֹמַיָּא:
@105 אֲרֵי אִלּוּלָפוֹן בְּדָא אִתְעַכָּבְנָא אֲרֵי כְעַן תַּבְנָא דְּנַן תַּרְתֵּין זִמְנִין:
@106 וַאֲמַר לְהוֹן יִשְׂרָאֵל אֲבוּהוֹן אִם כֵּן הָכָא דָּא עִיבִידוּ סִיבוּ מִדִּמְשַׁבַּח בְּאַרְעָא בְּמָנֵיכוֹן וְאוֹחִיתוּ לְגַבְרָא תִּקְרֻבְתָּא זְעֵיר קְטַף וּזְעֵיר דְּבַשׁ שְׁעַף וּלְטוֹם בָּטְנִין וְשִׁגְדִּין:
@107 וְכַסְפָּא עַל חַד תְּרֵין סִיבוּ בְיֶדְכוֹן וְיָת כַּסְפָּא דְּאִתּוֹתַב בְּפוּם טוֹעֲנֵיכוֹן תְּתִיבוּן בְּיֶדְכוֹן מָאִים שָׁלוּ הוּא:
@108 וְיָת אֲחוּכוֹן דְּבָרוּ וְקוּמוּ תּוּבוּ לְוַת גַּבְרָא:
@109 וְאֵל שַׁדַּי יִתֵּן לְכוֹן רַחֲמִין קֳדָם גַּבְרָא וְיִפְטַר לְכוֹן יָת אֲחוּכוֹן אָחֳרָנָא וְיָת בִּנְיָמִין וַאֲנָא כְּמָא דְּאִתְכֵּלִית תְּכֵלִית:
@110 וּנְסִיבוּ גֻּבְרַיָּא יָת תִּקְרֻבְתָּא הָדָא וְעַל חַד תְּרֵין כַּסְפָּא נְסִיבוּ בִידֵיהוֹן וּדְבָרוּ יָת בִּנְיָמִן וְקָמוּ וּנְחָתוּ לְמִצְרַיִם וְקָמוּ קֳדָם יוֹסֵף:
@111 וַחֲזָא יוֹסֵף עִמְּהוֹן יָת בִּנְיָמִין וַאֲמַר לְדִי מְמַנָּא עַל בֵּיתֵהּ אָעֵיל יָת גֻּבְרַיָּא לְבֵיתָא וּנְכוֹס נִכְסָתָא וְאַתְקֵין אֲרֵי עִמִּי יֵיכְלוּן גֻּבְרַיָּא בְּשֵׁירוּתָא:
@112 וַעֲבַד גַּבְרָא כְּמָא דִּי אֲמַר יוֹסֵף וְאָעֵיל גַּבְרָא יָת גֻּבְרַיָּא לְבֵית יוֹסֵף:
@113 וּדְחִילוּ גֻּבְרַיָּא אֲרֵי אִתַּעֲלוּ לְבֵית יוֹסֵף וַאֲמָרוּ עַל עֵסַק כַּסְפָּא דְּאִתּוֹתַב בְּטוֹעֲנָנָא בְּקַדְמֵיתָא אֲנַחְנָא מִתַּעֲלִין לְאִתְרַבְרָבָא עֲלָנָא וּלְאִסְתַּקָּפָא עֲלָנָא וּלְמִקְנֵי יָתָנָא לְעַבְדִּין וּלְמִדְבַּר יָת חֲמָרָנָא:
@114 וּקְרִיבוּ לְוַת גַּבְרָא דִּי מְמַנָּא עַל בֵּית יוֹסֵף וּמַלִּילוּ עִמֵּהּ בִּתְרַע בֵּיתָא:
@115 וַאֲמָרוּ בְּבָעוּ רִבּוֹנִי מֵיחַת נִחֵתְנָא בְּקַדְמֵיתָא לְמִזְבַּן עִיבוּרָא:
@116 וַהֲוָה כַּד אָתֵינָא לְבֵית מְבָתָא וּפְתַחְנָא יָת טוֹעֲנָנָא וְהָא כְסַף גְּבַר בְּפוּם טוֹעֲנֵהּ כַּסְפָּנָא בְּמַתְקְלֵהּ וַאֲתֵיבְנָא יָתֵהּ בִּידָנָא:
@117 וְכַסְפָּא אָחֳרָנָא אוֹחִיתְנָא בִידָנָא לְמִזְבַּן עִיבוּרָא לָא יְדַעְנָא מָן שַׁוִּי כַסְפָּנָא בְּטוֹעֲנָנָא:
@118 וַאֲמַר שְׁלַם לְכוֹן לָא תִדְחֲלוּן אֱלָהֲכוֹן וֵאֱלָהָא דַּאֲבוּכוֹן יְהַב לְכוֹן סִימָּא בְּטוֹעֲנֵיכוֹן כַּסְפְּכוֹן אֲתָא לְוָתִי וְאַפֵּיק לְוָתְהוֹן יָת שִׁמְעוֹן:
@119 וְאָעֵיל גַּבְרָא יָת גֻּבְרַיָּא לְבֵית יוֹסֵף וִיהַב מַיָּא וְאַסְחוֹ רִגְלֵיהוֹן וִיהַב כִּסְּתָא לַחֲמָרֵיהוֹן:
@120 וְאַתְקִינוּ יָת תִּקְרֻבְתָּא עַד דְּעַל יוֹסֵף בְּשֵׁירוּתָא אֲרֵי שְׁמָעוּ אֲרֵי תַמָּן יֵיכְלוּן לַחֲמָא:
@121 וְעַל יוֹסֵף לְבֵיתָא וְאַיְתִיאוּ לֵהּ יָת תִּקְרֻבְתָּא דִּי בִידֵיהוֹן לְבֵיתָא וּסְגִידוּ לֵהּ לְאַרְעָא:
@122 וּשְׁאֵיל לְהוֹן לִשְׁלַם וַאֲמַר הַשְׁלַם אֲבוּכוֹן סָבָא דִּי אֲמַרְתּוּן הַעַד כְּעַן קַיָּם:
@123 וַאֲמָרוּ שְׁלַם לְעַבְדָךְ לְאָבוּנָא עַד כְּעַן קַיָּם וּכְרָעוּ וּסְגִידוּ:
@124 וּזְקַף עֵינוֹהִי וַחֲזָא יָת בִּנְיָמִין אֲחוּהִי בַּר אִמֵּהּ וַאֲמַר הָדֵין אֲחוּכוֹן זְעֵירָא דִּי אֲמַרְתּוּן לִי וַאֲמַר מִן קֳדָם יְיָ יִתְרַחַם עֲלָךְ בְּרִי:
@125 וְאוֹחִי יוֹסֵף אֲרֵי אִתְגּוֹלְלוּ רַחֲמוֹהִי עַל אֲחוּהִי וּבְעָא לְמִבְכֵּי וְעַל לְאִדְרוֹן בֵּית מִשְׁכְּבָא וּבְכָא תַמָּן:
@126 וְאַסְחֵי אַפּוֹהִי וּנְפָק וְאִתְחַסִּין וַאֲמַר שַׁווּ לַחֲמָא:
@127 וְשַׁוִּיאוּ לֵהּ בִּלְחוֹדוֹהִי וּלְהוֹן בִּלְחוֹדֵיהוֹן וּלְמִצְרָאֵי דְּאָכְלִין עִמֵּהּ בִּלְחוֹדֵיהוֹן אֲרֵי לָא יָכְלִין מִצְרָאֵי לְמֵיכַל עִם עִבְרָאֵי לַחְמָא אֲרֵי בְעִירָא דְּמִצְרָאֵי דָחֲלִין לֵהּ עִבְרָאֵי אָכְלִין:
@128 וְאַסְחָרוּ קֳדָמוֹהִי רַבָּא כְּרַבְיוּתֵהּ וּזְעִירָא כִּזְעֵרוּתֵהּ וּתְמָהוּ גֻּבְרַיָּא גְּבַר לְחַבְרֵהּ:
@129 וּנְטַלּ חֳלָקִין מִן קֳדָמוֹהִי לָקֳדָמֵיהוֹן וּסְגִי חֲלָקָא דְבִנְיָמִן מֵחֳלָקֵי דְכָלְּהוֹן חַמְשָׁא חֳלָקִין וּשְׁתִיאוּ וּרְוִיאוּ עִמֵּהּ:
@130 וּפַקֵּיד יָת דִּי מְמַנָּא עַל בֵּיתֵהּ לְמֵימַר מְלֵי יָת טוֹעֲנֵי גֻּבְרַיָּא עִיבוּרָא כְּמָא דִּי יָכְלִין לְמִטְּעַן וְשַׁוִּי כְסַף גְּבַר בְּפוּם טוֹעֲנֵהּ:
@131 וְיָת כַּלִּידִי כַּלִּידָא דְכַסְפָּא תְּשַׁוֵּי בְּפוּם טוֹעֲנָא דִּזְעֵירָא וְיָת כְּסַף זְבִינוֹהִי וַעֲבַּד כְּפִתְגָּמָא דְּיוֹסֵף דִּי מַלִּיל:
@132 צַפְרָא נְהָר וְגֻבְרַיָּא אִתְפַּטָּרוּ אִנּוּן וַחֲמָרֵיהוֹן:
@133 אִנּוּן נְפָקוּ מִן קַרְתָּא לָא אַרְחִיקוּ וְיוֹסֵף אֲמַר לְדִי מְמַנָּא עַל בֵּיתֵהּ קוּם רְדַף בָּתַר גֻּבְרַיָּא וְתַדְבְּקִנּוּן וְתֵימַר לְהוֹן לְמָה שַׁלֶמְתּוּן בִּישָׁא חֳלָף טַבְתָא:
@134 הֲלָא דֵּין דְּשָׁתֵי רִבּוֹנִי בֵּהּ וְהוּא בָּדָקָא מְבָדֵק בֵּהּ אַבְאֶשְׁתּוּן דִּי עֲבַדְתּוּן:
@135 וְאַדְבֵּיקִנּוּן וּמַלֵּיל עִמְּהוֹן יָת פִּתְגָּמַיָּא הָאִלֵּין:
@136 וַאֲמָרוּ לֵהּ לְמָה יְמַלֵּל רִבּוֹנִי כְּפִתְגָּמַיָּא הָאִלֵּין חַס לְעַבְדָּיךְ מִלְּמֶעְבַּד כְּפִתְגָּמָא הָדֵין:
@137 הָא כַסְפָּא דִּי אַשְׁכַּחְנָא בְּפוּם טּוֹעֲנָנָא אֲתֵיבְנוֹהִי לָךְ מֵאַרְעָא דִּכְנָעַן וְאֶכְדֵּין נִגְנוּב מִבֵּית רִבּוֹנָךְ כַּסְפָּא אוֹ דַּהֲבָא (מָנִין דִּכְסַף אוֹ מָנִין דִּדְהָב):
@138 דִּי יִשְׁתְּכַח עִמֵּהּ מֵעַבְדָיךְ וּמִית וְאַף אַנַחְנָא נְהֵי לְרִבּוֹנִי לְעַבְדִין:
@139 וַאֲמַר אַף כְּעַן כְּפִתְגָּמֵיכוֹן כֶּן הוּא דִּי יִשְׁתְּכַח עִמֵּהּ יְהֵי לִי עַבְדָּא וְאַתּוּן תְּהוֹן זַכָּאִין:
@140 וְאוֹחִיאוּ וְאוֹחִיתוּ גְּבַר יָת טּוֹעֲנֵהּ לְאַרְעָא וּפְתָחוּ גְּבַר טוֹעֲנֵהּ:
@141 וּבְלַשׁ בְּרַבָּא שָׁרֵי וּבִזְעֵירָא שֵׁצִי וְאִשְׁתְּכַח כַּלִּידָא בְּטוֹעֲנָא דְבִנְיָמִן:
@142 וּבְזָעוּ לְבוּשֵׁיהוֹן וּרְמוֹ גְּבַר עַל חֲמָרֵהּ וְתָבוּ לְקַרְתָּא:
@143 וְעַל יְהוּדָּה וַאֲחוֹהִי לְבֵית יוֹסֵף וְהוּא עַד כְּעַן תַּמָּן וּנְפָלוּ קֳדָמוֹהִי לְאַרְעָא:
@144 וַאֲמַר לְהוֹן יוֹסֵף מָה עוֹבָדָא הָדֵין דִּי עֲבַדְתּוּן הֲלָא יְדַּעְתּוּן אֲרֵי בָדָקָא מְבָדֵק גַּבְרָא דִּי כְוָתִי:
@145 וַאֲמַר יְהוּדָה מַה נֵּימַר לְרִבּוֹנִי מַה נְּמַלֵּל וּמַה נִזְכֵּי מִן קֳדָם יְיָ אִשְׁתְּכַח יָת חוֹבָא דְעַבְדָּיךְ הָא אֲנַחְנָא עַבְדִּין לְרִבּוֹנִי אַף אֲנַחְנָא אַף דְּאִשְׁתְּכַח כַּלִּידָא בִּידֵהּ:
@146 וַאֲמַר חַס לִי מִלְּמֶעְבַּד דָּא גַּבְרָא דִּי אִשְׁתְּכַח כַּלִּידָא בִּידֵהּ הוּא יְהֵי לִי עַבְדָּא וְאַתּוּן סָקוֹ לִשְׁלַם לְוַת אֲבוּכוֹן: ססס:

@1 **ויהי מקץ.** כתרגומו מסוף, וכל לשון קץ סוף הוא: **על היאר.** כל שאר נהרות אינם קרויין יאורים חוץ מנילוס, מפני שכל הארץ עשוים יאורים יאורים בידי אדם ונילוס עולה בתוכם ומשקה אותם, לפי שאין גשמים יורדין במצרים תדיר כשאר ארצות:
@2 **יפות מראה.** סימן הוא לימי שובע, שהבריות נראות יפות זו לזו, שאין עין בריה צרה בחברתה: **באחו.** באגם, מריש''ק בלע''ז , כמו (איוב ח יא) ישגא אחו:
@3 **ודקות בשר.** טינבי''ש בלע''ז , לשון דק:
@4 **ותאכלנה.** סימן שתהא כל שמחת השובע נשכחת בימי הרעב:
@5 **בקנה אחד.** טודי''ל בלע''ז : **בריאות.** שייני''ש בלע''ז :
@6 **ושדופת.** השלידי''ש בלע''ז ושקיפן קדום, חבוטות לשון משקוף החבוט תמיד על ידי הדלת המכה עליו: **קדים.** רוח מזרחית שקורין ביש''א :
@7 **הבריאות.** שייני ''ש בלע''ז : **והנה חלום.** והנה נשלם חלום שלם לפניו והצרך לפותרים:
@8 **ותפעם רוחו.** ומטרפא רוחה מקשקשת בתוכו כפעמון. ובנבוכדנצר הוא אומר (דניאל ב א) ותתפעם רוחו, לפי שהיו שם שתי פעימות שכחת החלום והעלמת פתרונו: **חרטמי.** הנחרים בטימי מתים, ששואלים בעצמות. טימי, הן עצמות בלשון ארמי, ובמשנה בית שהוא מלא טמיא, מלא עצמות: **ואין פותר אותם לפרעה.** פותרים היו אותם, אבל לא לפרעה, שלא היה קולן נכנס באזניו, ולא היה לו קורת רוח בפתרונם, שהיו אומרים שבע בנות אתה מוליד, שבע בנות אתה קובר:
@11 **איש כפתרון חלומו.** חלום הראוי לפתרון שנפתר לו ודומה לו:
@12 **נער עברי עבד.** ארורים הרשעים שאין טובתם שלמה. מזכירו בלשון בזיון: **נער.** שוטה ואין ראוי לגדלה: **עברי.** אפילו לשוננו אינו מכיר: **עבד.** וכתוב בנמוסי מצרים שאין עבד מולך ולא לובש בגדי שרים: **איש כחלומו.** לפי החלום וקרוב לענינו:
@13 **השיב על כני.** מי שבידו להשיב, והוא פרעה הנזכר למעלה, כמו שאמר (לעיל י) פרעה קצף על עבדיו, הרי מקרא קצר ולא פרש מי השיב, לפי שאין צריך לפרש מי השיב, וכן דרך כל מקראות קצרים על מי שעליו לעשות הם סותמים את הדבר:
@14 **מן הבור.** מן בית הסוהר שהוא עשוי כמין גמא, וכן כל בור שבמקרא לשון גמא הוא, ואף אם אין בו מים קרוי בור פוש''א בלע''ז : **ויגלח.** מפני כבוד המלכות:
@15 **תשמע חלום לפתר אתו.** תאזין ותבין חלום לפתר אתו: **תשמע.** לשון הבנה והאזנה, כמו (להלן מב כג) שומע יוסף, (דברים כח מט) אשר לא תשמע לשונו, אינטינדר''א בלע''ז :
@16 **בלעדי.** אין החכמה משלי אלא אלהים יענה, יתן עניה בפי לשלום פרעה:
@19 **דלות.** כחושות, כמו (ש''ב יג ד) מדוע אתה ככה דל, דאמנון: **ורקות בשר.** כל לשון רקות שבמקרא חסרי בשר, ובלע''ז בלושי''ש :
@23 **צנמות.** צונמא בלשון ארמי סלע, הרי הן כעץ בלי לחלוח, וקשות כסלע, ותרגומו נצן לקין, נצן אין בהן אלא הנץ לפי שנתרוקנו מן הזרע:
@26 **שבע שנים' שבע שנים.** כלן אינן אלא שבע, ואשר נשנה החלום פעמים לפי שהדבר מזמן, כמו שפרש לו בסוף (פסוק לב) ועל השנות החלום וגו' . בשבע שנים הטובות נאמר (פסוק כה) הגיד לפרעה, לפי שהיה סמוך, ובשבע שני רעב נאמר (פסוק כח) הראה את פרעה, לפי שהיה הדבר מפלג ורחוק, נופל בו לשון מראה:
@30 **ונשכח כל השבע.** הוא פתרון הבליעה:
@31 **ולא יודע השבע.** הוא פתרון (פסוק כא) ולא נודע כי באו אל קרבנה:
@32 **נכון.** מזמן:
@34 **וחמש.** כתרגומו ויזרזון וכן (שמות יג יח) וחמושים:
@35 **את כל אכל.** שם דבר הוא, לפיכך טעמו באל''ף ונקוד בפתח קטן, ואוכל שהוא פועל, כגון (ויקרא ז כה) כי כל אכל חלב, טעמו למטה בכף ונקוד קמץ קטן: **תחת יד פרעה.** ברשותו ובאוצרותיו:
@36 **והיה האכל.** הצבור כשאר פקדון הגנוז לקיום הארץ:
@38 **הנמצא כזה.** הנשכח כדין, אם נלך ונבקשנו הנמצא כמוהו. הנמצא לשון תמיהה, וכן כל ה''א המשמשת בראש תבה ונקודה בחטף פתח:
@39 **אין נבון וחכם כמוך.** לבקש איש נבון וחכם שאמרת, לא נמצא כמוך:
@40 **ישק.** יתזן, יתפרנס. כל צרכי עמי יהיו נעשים על ידך, כמו (לעיל טו ב) ובן משק ביתי, וכמו (תהלים ב יב) נשקו בר, גרנישו''ן בלע''ז : **רק הכסא.** שיהיו קורין לי מלך: **כסא.** לשון שם המלוכה כמו (מלכים א א לז) ויגדל את כסאו מכסא אדני המלך:
@41 **נתתי אתך.** מניתי יתך, ואף על פי כן לשון נתינה הוא, כמו (דברים כו יט) ולתתך עליון, בין לגדלה בין לשפלות נופל לשון נתינה עליו, כמו (מלאכי ב ט) נתתי אתכם נבזים ושפלים:
@42 **ויסר פרעה את טבעתו.** נתינת טבעת המלך הוא אות למי שנותנה לו להיות שני לו לגדלה: **בגדי שש.** דבר חשיבות הוא במצרים: **רבד.** ענק, ועל שהוא רצוף בטבעות קרוי רביד. וכן (משלי ז טז) רבדתי ערשי, רצפתי ערשי מרצפות. בלשון משנה (מדות א ח) מקף רבדין של אבן, (יומא מג ב) על הרובד שבעזרה, והיא רצפה:
@43 **במרכבת המשנה.** השניה למרכבתו, המהלכת אצל שלו: **אברך.** כתרגומו דין אבא למלכא. רך בלשון ארמי מלך. בהשותפין (בבא בתרא ד א) לא ריכא ולא בר ריכא. ובדברי אגדה דרש ר' יהודה אברך זה יוסף שהוא אב בחכמה ורך בשנים, אמר לו רבי יוסי בן דורמסקית עד מתי אתה מעות עלינו את הכתובים, אין אברך אלא לשון ברכים, שהכל היו נכנסין ויוצאין תחת ידו, כענין שנאמר ונתון אותו וגו' :
@44 **אני פרעה.** שיש יכולת בידי לגזור גזרות על מלכותי, ואני גוזר שלא ירים איש את ידו: **ובלעדיך.** שלא ברשותך. דבר אחר אני פרעה אני אהיה מלך ובלעדיך וגו' וזהו דגמת (פסוק מ) רק הכסא: **את ידו ואת רגלו.** כתרגומו:
@45 **צפנת פענח.** מפרש הצפונות, ואין לפענח דמיון במקרא: **פוטי פרע.** הוא פוטיפר, ונקרא פוטיפרע על שנסתרס מאליו, לפי שלקח את יוסף למשכב זכר:
@47 **ותעש הארץ.** כתרגומו, ואין הלשון נעקר מלשון עשייה: **לקמצים.** קומץ על קומץ, יד על יד היו אוצרים:
@48 **אכל שדה העיר אשר סביבתיה נתן בתוכה.** שכל ארץ וארץ מעמדת פירותיה ונותנין בתבואה מעפר המקום ומעמיד את התבואה מלירקב:
@49 **עד כי חדל לספר.** עד כי חדל לו הסופר לספר, והרי זה מקרא קצר: **כי אין מספר.** לפי שאין מספר, והרי כי משמש בלשון דהא:
@50 **בטרם תבוא שנת הרעב.** מכאן שאסור לאדם לשמש מטתו בשני רעבון:
@55 **ותרעב כל ארץ מצרים.** שהרקיבה תבואתם שאצרו חוץ משל יוסף: **אשר יאמר לכם תעשו.** לפי שהיה יוסף אומר להם שימולו, וכשבאו אצל פרעה ואומרים כך הוא אומר לנו, אמר להם למה לא צברתם בר, והלא הכריז לכם ששני הרעב באים, אמרו לו אספנו הרבה והרקיבה, אמר להם אם כן כל אשר יאמר לכם תעשו, הרי גזר על התבואה והרקיבה, מה אם יגזור עלינו ונמות:
@56 **על כל פני הארץ.** מי הם פני הארץ, אלו העשירים: **את כל אשר בהם.** כתרגומו די בהון עבורא: **וישבר למצרים.** שבר לשון מכר ולשון קנין הוא, כאן משמש לשון מכר, (להלן מג ב) שברו לנו מעט אכל, לשון קנין. ואל תאמר אינו כי אם בתבואה, שאף ביין וחלב מצינו (ישעיה נה א) ולכו שברו בלא כסף ובלא מחיר יין וחלב:
@57 **וכל הארץ באו מצרימה לשבר אל יוסף.** (סרסהו ופרשהו וכל הארץ באו מצרים אל יוסף) . אם תפרשהו כסדרו היה צריך לכתוב לשבור מן יוסף:
@58 **וירא יעקב כי יש שבר במצרים.** ומהיכן ראה, והלא לא ראה אלא שמע, שנאמר (להלן מב ב) הנה שמעתי וגו' , ומהו וירא, ראה באספקלריא של קדש שעדין יש לו שבר סבר במצרים. ולא היתה נבואה ממש להודיעו בפרוש שזה יוסף: **למה תתראו.** למה תראו עצמכם בפני בני ישמעאל ובני עשו כאלו אתם שבעים, שבאותה שעה עדין היה להם תבואה. [ולי נראה כפשוטו למה תתראו, למה יהיו הכל מסתכלין בכם ומתמיהים בכם שאין אתם מבקשים לכם אכל בטרם שיכלה מה שבידכם]. ומפי אחרים שמעתי שהוא לשון כחישה, למה תהיו כחושים ברעב. ודומה לו (משלי יא כה) ומרוה גם הוא יורא:
@59 **רדו שמה.** ולא אמר לכו, רמז למאתים ועשר שנים שנשתעבדו למצרים, כמנין רד''ו:
@60 **וירדו אחי יוסף.** ולא כתב בני יעקב, מלמד שהיו מתחרטים במכירתו ונתנו לבם להתנהג עמו באחוה ולפדותו בכל ממון שיפסקו עליהם: **עשרה.** מה תלמוד לומר, והלא כתיב (פסוק ד) ואת בנימין אחי יוסף לא שלח, אלא לענין האחוה היו חלוקין לעשרה, שלא היתה אהבת כלם ושנאת כלם שוה לו, אבל לענין לשבור בר כלם לב אחד להם:
@61 **פן יקראנו אסון.** ובבית לא יקראנו אסון, אמר רבי אלעזר בן יעקב מכאן שהשטן מקטרג בשעת הסכנה:
@62 **בתוך הבאים.** מטמינין עצמן שלא יכירום, לפי שצוה להם אביהם שלא יתראו כלם בפתח אחד אלא שיכנס כל אחד בפתחו, כדי שלא תשלט בהם עין הרע שכלם נאים וכלם גבורים: [ כי היה הרעב . מוסב על הבאים , כי היה הרעב בארץ כנען והיו באים הרבה שירות משם]:
@63 **וישתחוו לו אפים.** נשתטחו לו על פניהם, וכן כל השתחואה פשוט ידים ורגלים היא:
@64 **ויתנכר אליהם.** נעשה להם כנכרי בדברים, לדבר קשות:
@65 **ויכר יוסף** וגו' **.** לפי שהניחם חתומי זקן: **והם לא הכרהו.** שיצא מאצלם בלא חתימת זקן, ועכשיו בא בחתימת זקן. ומדרש אגדה ויכר יוסף את אחיו כשנמסרו בידו הכיר שהם אחיו ורחם עליהם, והם לא הכירוהו כשנפל בידם לנהוג בו אחוה:
@66 **אשר חלם להם.** עליהם, וידע שנתקימו, שהרי השתחוו לו: **ערות הארץ.** גלוי הארץ, מהיכן היא נוחה לכבש, כמו (ויקרא כ יח) את מקורה הערה, וכמו (יחזקאל טז ז) ערום ועריה. וכן כל ערוה שבמקרא לשון גלוי. ותרגום אנקלוס בדקא דארעא, כמו (מלכים ב' יב ו) בדק הבית, רעוע הבית, אבל לא דקדק לפרשו אחר לשון המקרא:
@67 **לא אדני.** לא תאמר כן, שהרי עבדיך באו לשבר אכל:
@68 **כלנו בני איש אחד נחנו.** נצנצה בהם רוח הקדש וכללוהו עמהם שאף הוא בן אביהם: **כנים.** אמתיים, כמו (שמות י כט) כן דברת, (במדבר כז ז) כן בנות צלפחד דוברות, (ישעיה טז ו) ועברתו לא כן בדיו:
@69 **כי ערות הארץ באתם לראות.** שהרי נכנסתם בעשרה שערי העיר, למה לא נכנסתם בשער אחד:
@70 **ויאמרו שנים עשר עבדיך** וגו' **.** ובשביל אותו אחד שאיננו נתפזרנו בעיר לבקשו:
@71 **הוא אשר דברתי.** הדבר אשר דברתי שאתם מרגלים הוא האמת והנכון, זהו לפי פשוטו. ומדרשו אמר להם ואלו מצאתם אותו ויפסקו עליכם ממון הרבה תפדוהו. אמרו לו הן. אמר להם ואם יאמרו לכם שלא יחזירוהו בשום ממון מה תעשו. אמרו לו לכך באנו, להרוג או להרג, אמר להם הוא אשר דברתי אליכם להרוג בני העיר באתם, מנחש אני בגביע שלי ששנים מכם החריבו כרך גדול של שכם:
@72 **חי פרעה.** אם יחיה פרעה. שהיה נשבע לשקר, היה נשבע בחיי פרעה: **אם תצאו מזה.** מן המקום הזה:
@73 **האמת אתכם.** אם אמת אתכם. לפיכך ה''א נקוד פתח שהוא כמו בלשון תמה. ואם לא תביאוהו, חי פרעה כי מרגלים אתם:
@74 **משמר.** בית האסורים:
@76 **בבית משמרכם.** שאתם אסורים בו עכשיו: **ואתם לכו הביאו.** לבית אביכם: **שבר רעבון בתיכם.** מה שקניתם לרעבון אנשי בתיכם:
@77 **ויאמנו דבריכם.** יתאמתו ויתקימו, כמו (במדבר ה כב) אמן אמן, וכמו (מ''א ח כו) יאמן נא דברך:
@78 **אבל.** כתרגומו בקושטא. וראיתי בבראשית רבה (צא ח) לישנא דרומאה היא אבל, ברם: **באה אלינו.** טעמו בבי''ת, לפי שהוא בלשון עבר שכבר באה, ותרגומו אתת לנא:
@79 **וגם דמו.** אתין וגמין רבויין, דמו וגם דם הזקן:
@80 **והם לא ידעו כי שומע יוסף.** מבין לשונם ובפניו היו מדברים כן: **כי המליץ בינתם.** כי כשהיו מדברים עמו היה המליץ ביניהם, היודע לשון עברי ולשון מצרי, והיה מליץ דבריהם ליוסף ודברי יוסף להם, לכך היו סבורים שאין יוסף מכיר בלשון עברי: **המליץ.** זה מנשה:
@81 **ויסב מעליהם.** נתרחק מעליהם שלא יראוהו בוכה: **ויבך.** לפי ששמע שהיו מתחרטין: **את שמעון.** הוא השליכו לבור, הוא שאמר ללוי (לעיל לז יט) הנה בעל החלומות הלזה בא. דבר אחר נתכון יוסף להפרידו מלוי שמא יתיעצו שניהם להרוג אותו: **ויאסור אותו לעיניהם.** לא אסרו אלא לעיניהם, וכיון שיצאו הוציאו והאכילו והשקהו:
@84 **ויפתח האחד.** הוא לוי שנשאר יחיד משמעון בן זוגו: **במלון.** במקום שלנו בלילה: **אמתחתו.** הוא שק:
@85 **וגם הנה באמתחתי.** גם הכסף בו עם התבואה: **מה זאת עשה אלהים לנו.** להביאנו לידי עלילה זו שלא הושב אלא להתעולל עלינו:
@91 **ואת הארץ תסחרו.** תסובבו. וכל לשון סוחרים וסחורה על שם שמחזרים וסובבים אחר פרקמטיא:
@92 **צרור כספו.** קשר כספו:
@93 **אתי שכלתם.** מלמד שחשדן שמא הרגוהו או מכרוהו כיוסף: **שכלתם.** כל מי שבניו אבודים קרוי שכול:
@95 **לא ירד בני עמכם.** לא קבל דבריו של ראובן. אמר בכור שוטה הוא זה, הוא אומר להמית בניו, וכי בניו הם ולא בני:
@97 **כאשר כלו לאכל.** יהודה אמר להם המתינו לזקן עד שתכלה פת מן הבית: **כאשר כלו.** כד שציאו. והמתרגם כד ספיקו, טועה כאשר כלו הגמלים לשתות מתרגם כד ספיקו כששתו די ספוקם הוא גמר שתיתם. אבל זה כאשר כלו לאכול, כאשר תם האכל הוא, ומתרגמינן כד שציאו:
@98 **העד העד.** לשון התראה, שסתם התראה מתרה בו בפני עדים, וכן (ירמיהו יא ז) העדתי באבותיכם, (שמות יט כא) רד העד בעם: **לא תראו פני בלתי אחיכם אתכם.** לא תראוני בלא אחיכם אתכם. ואנקלוס תרגם אלהין כד אחוכון עמכון, ישב באור הדבר על אפנו ולא דקדק לתרגם אחר לשון המקרא:
@102 **לנו ולמולדתנו.** למשפחותינו, ומדרשו אפילו עצי עריסותינו גלה לנו: **ונגד לו.** שיש לנו אב ואח: **על פי הדברים האלה.** על פי שאלותיו אשר שאל הזקקנו להגיד: **כי יאמר.** אשר יאמר, כי משמש בלשון אם, ואם משמש בלשון אשר. הרי זה שמוש אחד מארבע לשונותיו שמשמש כי, והוא אם, שהרי כי זה כמו אם, כמו עד אם דברתי דברי (כד לג) :
@103 **ונחיה.** נצנצה בו רוח הקדש, על ידי הליכה זו תחי רוחך שנאמר (מה כז) ותחי רוח יעקב אביהם: **ולא נמות.** ברעב. בנימין ספק יתפש ספק לא יתפש, ואנו כלנו מתים ברעב אם לא נלך, מוטב שתניח את הספק ותתפוש את הודאי:
@104 **והצגתיו לפניך.** שלא אביאנו אליך מת כי אם חי: **וחטאתי לך כל הימים.** לעולם הבא:
@105 **לולא התמהמהנו.** על ידך, כבר היינו שבים עם שמעון ולא נצטערת כל הימים הללו:
@106 **אפוא.** כל לשון אפוא לשון יתר הוא לתקון מלה בלשון עברי, אם כן אזדקק לעשות שאשלחנו עמכם, צריך אני לחזור ולבקש איה פה תקנה ועצה להשיאכם, ואומר אני זאת עשו: **מזמרת הארץ.** מתרגם מדמשבח בארעא שהכל מזמרים עליו כשהוא בא לעולם: **נכאת.** שעוה: **בטנים.** לא ידעתי מה הם ובפרושי א' ב' של רבי מכיר ראיתי פישיטצי''ש [פיסטוקים] ודומה לי שהם אפרסקין:
@107 **וכסף משנה.** פי שנים כראשון: **קחו בידכם.** לשבור אוכל, שמא הוקר השער: **אולי משגה הוא.** שמא הממנה על הבית שכחו שוגג:
@109 **ואל שדי.** מעתה אינכם חסרים כלום אלא תפלה, הריני מתפלל עליכם: **ואל שדי.** שדי בנתינת רחמיו, וכדי היכולת בידו לתן, יתן לכם רחמים, זהו פשוטו. ומדרשו מי שאמר לעולם די יאמר די לצרותי, שלא שקטתי מנעורי, צרת לבן, צרת עשו, צרת רחל, צרת דינה, צרת יוסף, צרת שמעון, צרת בנימין: **ושלח לכם.** ויפטר לכון, תרגומו, יפטרנו מאסוריו, לשון (שמות כא כו) לחפשי ישלחנו, ואינו נופל בתרגום לשון וישלח, שהרי לשם הם הולכים אצלו: **את אחיכם.** זה שמעון: **אחר.** רוח הקדש נזרקה בו, לרבות יוסף: **ואני.** עד שובכם אהיה שכול מספק: **כאשר שכלתי.** מיוסף ומשמעון: **שכלתי.** מבנימין:
@110 **ואת בנימין.** מתרגמינן ודברו ית בנימין, לפי שאין לקיחת הכסף ולקיחת האדם שוה בלשון ארמי, בדבר הנקח ביד מתורגם ונסיב, ודבר הנקח בהנהגת דברים מתרגמינן ודבר:
@111 **וטבוח טבח והכן.** כמו ולטבוח טבח ולהכין, ואין טבוח לשון צווי שהיה לו לומר וטבח: **בצהרים.** זה מתורגם בשירותא, שהוא לשון סעודה ראשונה בלשון ארמי, ובלע''ז דישני''ר [ארוחת צהרים], ויש הרבה בתלמוד (תענית יא ב) שדא לכלבא שירותיה, (ברכות לט ב) בצע אכולא שירותיה. אבל כל תרגום של צהרים טיהרא:
@113 **וייראו האנשים.** כתוב בשני יודי''ן ותרגומו ודחילו: **כי הובאו בית יוסף.** ואין דרך שאר הבאים לשבור בר ללון בבית יוסף, כי אם בפנדקאות שבעיר. וייראו שאין זה אלא לאספם אל משמר: **אנחנו מובאים.** אל תוך הבית הזה: **להתגולל.** להיות מתגלגלת עלינו עלילת הכסף ולהיותה נופלת עלינו. ואונקלוס שתרגם ולאסתקפא עלנא, הוא לשון להתעולל, כדמתרגמינן (דברים כב יד) עלילת דברים תסקופי מלין, ולא תרגמו אחר לשון המקרא, ולהתגלל שתרגם לאתרברבא הוא לשון (קהלת יב ו) גלת הזהב, (נחום ב ח) והצב גלתה העלתה, שהוא לשון מלכות:
@115 **בי אדני.** לשון בעיא ותחנונים הוא, ובלשון ארמי בייא בייא: **ירד ירדנו.** ירידה היא לנו, רגילים היינו לפרנס אחרים, עכשיו אנו צריכים לך:
@118 **אלהיכם.** בזכותכם, ואם אין זכותכם כדאי, ואלהי אביכם, בזכות אביכם נתן לכם מטמון:
@119 **ויבא האיש.** הבאה אחר הבאה, לפי שהיו דוחפים אותו לחוץ עד שדברו אליו פתח הבית, ומשאמר להם (פסוק כג) שלום לכם, נמשכו ובאו אחריו:
@120 **ויכינו.** הזמינו, עטרוה בכלים נאים:
@121 **הביתה.** מפרזדור לטרקלין:
@123 **ויקדו וישתחוו.** על שאילת שלום. קידה כפיפת קדקד, השתחואה משתטח לארץ:
@124 **אלהים יחנך בני.** בשאר שבטים שמענו חנינה (לעיל לג ה) אשר חנן אלהים את עבדך, ובנימין עדיין לא נלד, לכך ברכו יוסף בחנינה:
@125 **כי נכמרו רחמיו.** שאלו יש לך אח מאם, אמר לו אח היה לי ואיני יודע היכן הוא. יש לך בנים, אמר לו יש לי עשרה, אמר לו ומה שמם, אמר לו (להלן מו כא) בלע ובכר וגו' , אמר לו מה טיבן של שמות הללו, אמר לו כלם על שם אחי והצרות אשר מצאוהו, בלע שנבלע בין האמות. בכר שהיה בכור לאמי. אשבל ששבאו אל. גרא שנתגייר באכסניא. ונעמן, שהיה נעים ביותר. אחי וראש אחי היה וראשי היה. מפים מפי אביו למד. וחפים שלא ראה חפתי ולא ראיתי אני חפתו. וארד שירד לבין האמות, כדאיתא במסכת סוטה (לו ב) מיד נכמרו רחמיו: **נכמרו.** נתחממו, ובלשון משנה (ב''מ עד א) על הכמר של זיתים, ובלשון ארמי מכמר בשרא, ובמקרא (איכה ה י) עורנו כתנור נכמרו, נתחממו ונקמטו קמטים קמטים מפני זלעפות רעב. כן דרך כל עור כשמחממין אותו נקמט וכווץ:
@126 **ויתאפק.** נתאמץ. והוא לשון (איוב יב כא) ומזיח אפיקים רפה, וכן (איוב מא ז) אפיקי מגנים, חוזק:
@127 **כי תועבה הוא.** דבר שנאוי הוא למצרים לאכול את העברים, ואונקלוס נתן טעם לדבר:
@128 **הבכור כבכורתו.** מכה בגביע וקורא ראובן שמעון לוי ויהודה יששכר וזבולון, בני אם אחת, הסבו כסדר הזה שהוא סדר תולדותיכם וכן כלם, כיון שהגיע לבנימין אמר זה אין לו אם ואני אין לי אם ישב אצלי:
@129 **משאת.** מנות: **חמש ידות.** חלקו עם אחיו ומשאת יוסף ואסנת ומנשה ואפרים: **וישכרו עמו.** ומיום שמכרוהו לא שתו יין, ולא הוא שתה יין, ואותו היום שתו
@131 **גביע.** כוס ארוך, וקורין לו מדירנ''א בלע''ז :
@136 **חלילה לעבדיך.** חלין הוא לנו, לשון גנאי. ותרגום חס לעבדיך, חס מאת הקדוש ברוך הוא יהי עלינו מעשות זאת והרבה חס ושלום יש בתלמוד בלשון הזה:
@137 **הן כסף אשר מצאנו.** זה אחד מעשרה קל וחמר האמורים בתורה. וכלן מנויין בבר' רבה:
@139 **גם עתה כדבריכם.** אף זו מן הדין, אמת כדבריכם כן הוא שכלכם חיבים בדבר, עשרה שנמצאת גנבה ביד אחד מהם כלם נתפשים, אבל אני אעשה לכם לפנים משורת הדין, אשר ימצא אתו יהיה לי עבד:
@141 **בגדול החל.** שלא ירגישו בו שהיה יודע היכן הוא:
@142 **ויעמס איש על חמרו.** בעלי זרוע היו ולא הצרכו לסיע זה את זה לטעון: **וישבו העירה.** מטרפולין היתה והוא אומר העירה, עיר כל שהיא, אלא שלא היתה חשובה בעיניהם אלא כעיר בינונית של עשרה בני אדם לענין המלחמה:
@143 **עודנו שם.** שהיה ממתין להם:
@144 **הלוא ידעתם כי נחש ינחש** וגו' **.** הלא ידעתם כי איש חשוב כמוני יודע לנחש ולדעת מדעת ומסברא ובינה כי אתם גנבתם הגביע:
@145 **האלהים מצא.** יודעים אנו שלא סרחנו, אבל מאת הקדוש ברוך הוא נהיתה להביא לנו זאת. מצא בעל חוב מקום לגבות שטר חובו: **ומה נצטדק.** לשון צדק, וכן כל תבה שתחלת יסודה צד''י והיא באה לדבר בלשון מתפעל או נתפעל נותן טי''ת במקום תי''ו, ואינה נתנת לפני אות ראשונה של יסוד התבה אלא באמצע אותיות העקר, כגון נצטדק מגזרת צדק, (דניאל ד ל) ויצטבע מגזרת צבע, (יהושע ט ד) ויצטירו מגזרת (משלי יג יז) ציר אמונים, (יהושע ט יב) הצטידנו מגזרת (לעיל מב כה) צדה לדרך. ותיבה שתחלתה סמ''ך או שי''ן כשהיא מתפעלת התי''ו מפרדת את אותיות העקר, כגון (קהלת יב ה) ויסתבל החגב, מגזרת סבל, (דניאל ז ח) משתכל הוית בקרניא, (מיכה ו טז) וישתמר חקות עמרי, מגזרת שמר, (ישעיה נט טו) וסר מרע משתולל, מגזרת (איוב יב יז) מוליך יועצים שולל, (שמות ט יז) מסתולל בעמי, מגזרת (ירמיה יח טו) דרך לא סלולה:

@1 **שנתים ימים.** הם שתי שנים. וזה החשבון ידמה שהיה מעת צאת שר המשקים מהסוהר ובסוף השתי שנים חלם פרעה זה החלום.
@3 **ודקות בשר.** הוא מעניין הדלות והרקיקות. והנה היו שבע הפרות בריאות. משל לשבע שני השבע. ושבע הפרות דלות הבשר שעולות אחריהן. משל לשבע שני הרעב שיבאו אחריהן ואכילת הפרות דקות הבשר את הבריאות הוא משל שתבואת שני השבע תאכל בשבע שני הרעב וזה ממה שספר פרעה אחר זה ולא נודע כי באו אל קרבנה הוא לאות שלא יודע השבע בארץ מפני הרעב שיהיה אחרי כן וזה ממה שחייב שיתקבצו אוכל השנים הטובות כדי שיהיה מזון מוכן להם בשני הרעב כמו שיעץ יוסף לפרעה. ולזה היתה זאת העצה באופן מה מפתרון החלום ומשל השבולים הוא יותר מיוחד בזה כי הוא היה בנושא בעינו אשר היה בו הפתרון.
@8 **ותפעם רוחו.** מרוב המבוכה אשר היתה נוטה מחשבתו פעם לדבר אחד ופעם לדבר אחר בעניין פתרון זה החלם במדרגת האיש הנבוך. והנה היתה רוחו במדרגת הפעמון שיכה פעם לצד אחד ופעם לצד שני והיה זה הענין הוא מסגלת החלומות הצודקים ר"ל שיגיע מהם התפעמות הרוח לפי שכבר ישער האדם בהם שהם צודקים. ועוד כי מפני התבודדות הנפלא שהיה לדמיון מבין כחות הנפש עד שקבל זה השפע יגילו לו זה ההפעלות כמו שביארנו בספר מלחמות יי'.
@8 **חרטומי מצרים.** הם המכשפים.
@8 **ואין פותר אותם לפרעה.** ר"ל שלא היה אחד מהם פותר אותם באופן שיתישב הפתרון ההוא בלב פרעה.
@9 **את חטאי אני מזכיר.** ר"ל כבר יביאני ההכרח להזכיר חטאי כדי שאודיע למלך מי יתכן שיפתור לו חלומותיו.
@14 **ויגלח ויחלף שמלותיו.** לכבוד המלך.
@15 **תשמע חלום.** הוא הווה והרצון בו שאתה שומע חלום ומבין אותו לפתרו.
@16 **בלעדי אלהים יענה את שלום פרעה.** הורהו בזה שאין בבחירתו לפתור לפי מה שירצה אבל יפתור לו לפי מה שיראוהו מן השמים ולזה התפלל לשם יתע' שיהיה פתרון החלום שלום פרעה.
@23 **צנומות.** קשות ויבשות שלא נשאר בהם כי אם מעט זולת הסובין.
@33 **ירא פרעה איש נבון וחכם.** הנה הוצרך לזה כדי שיהיה על הפקידים וישגיח במה שיעשוהו עד שלא יוכל אחד מהם לגנוב דבר. ולזה הוצרך שיהיה איש נבון וחכם ועוד שהאיש ההוא יעשה בחכמתו עם אנשי הארץ שיתרצו במה שיעשה.
@34 **וחמש.** הוא מעניין וחמושים או ירצה בו שיקנה החמש מכל תבואות השנים ההם.
@35 **ויצברו.** ויאספו.
@35 **תחת יד פרעה.** באוצרותיו.
@38 **הנמצא הזה.** הוא עתיד ור"ל מה שאמ' יוסף שנבקש איש נבון וחכם הנה אם נבקשהו לא נמצא נבון וחכם בזה שרוח אלהים בו.
@40 **ישק.** מעניין נשק וכלי זיין ר"ל שלא ישא אחד מהם כלי זיין ולא יצא למלחמה אם לא במצות יוסף.
@40 **רק הכסא אגדל ממך.** אהיה גדל ור"ל כי בכסא לבד אהיה גדול ממך שאני לבדי אשב על כסא המלוכה.
@42 **את טבעתו.** בה היה חותם המלך ונתנה ליוסף לחתום בשמו כל מה שירצה.
@42 **וילבש אותו בגדי שש.** הם היו יקרים מאד בארץ מצרים.
@42 **רביד.** ענק.
@43 **במרכבת המשנה.** הוא המרכבה שהיה רוכב בה מי שהוא משנה אל המלך.
@43 **אברך.** כמו הברך וכמהו אשכם ושלוח רוצה לומר שכבר הכריזו לפניו שיחלקו לו כבוד ויברכו על ברכיהם לפניו.
@44 **את ידו ואת רגלו.** רוצה לומ' שלא יעשו דבר ולא ילכו למקום אם לא ברשותך. והרצון בו שאתה תמשול בהנהגתם בכללה ואמר שלא ירים איש מבלעדיו את ידו ואת רגלו על צד ההפלגה או יהיה פירושו כדברי המתרגם כי במצרים לא יהיה רשות לאדם לרכוב על סוס אם לא ירשהו המלך על זה אבל הם כלם רוכבים על חמורים והיה זה כן כי לרוב המצא הסוסים במצרים לא יוכר בין השרים והעבדים אם יהיה רשות לכלם לרכוב על סוס וכן הענין בבגדי שש כי הם נמצאים שם מאד.
@45 **צפנת פענח.** הוא לפי מה שאחשוב שם שהוא מורה על רוב הבינה והחכמה וידיעת סודות המציאות או היה שם אלי פרעה כן כמו ששם נבוכדנצר שם דניאל כשם אלהיו והביאור הראשון הוא יותר נאות.
@45 **פוטיפרע.** אמרו ז"ל שהוא פוטיפר אדוניו.
@45 **כהן און.** אדון און כטעם ובני דוד כהנים היו.
@45 **ויצא יוסף על ארץ מצרים.** רוצה לומר שכבר רכב במרכבת המשנה ויצא על ארץ מצרים ואז חלקו לו כבוד כלם ונתברר להם שהוא עליהם ושהוא משנה למלך.
@46 **ויעבור בכל ארץ מצרים.** להשגיח בעניני הארץ כי אליו נתן פרעה זה הפקידות.
@47 **לקמצים.** ירצה לפי מה שאפשר לחשוב שבשבולת אחת היתה מלא קמצם בר ואמר זה על דרך הפלגה והגוזמא.
@48 **ויקבוץ את כל האכל.** ר"ל כל האוכל שהיה יכול לקבץ אחר שהשאיר לעם הארץ מה שיספיק להם לאכול ולזרוע ונתן אוכל כל עיר בתוכה כי בזה יסכימו יותר אנשי העיר לתת בידו תבואתם אם על צד המתנה אם על צד המכר אחר שיבטחו שהוא יהיה מוכן להם שם בעת הצורך וזה כי כל אדם יבחר המזון הנהוג לו על הבלתי נהוג לו ולזה יאהב כל אדם יין מדינתו ותבואת מדינתו.
@49 **כי אין מספר.** אמר זה על צד ההפלגה והגוזמא כי כבר היה לו מספר בהכרח אך לקושי המנותו יאמר שאין לו מספר.
@51 **כי נשני אלהים אל כל עמלי.** ר"ל כי שכח אותי השם כל מה שעברו עלי מהתלאות ושכח אותי את כל בית אבי מרוב הטובה שחנן אותי לא תדאג נפשי לדבר מזה.
@54 **ויהי רעב בכל הארצות.** ר"ל שהיו סביבות ארץ מצרים.
@54 **ובכל ארץ מצרים היה לחם.** לפי שכבר אצר יוסף אוצרות רבות בכל אחת מערי מצרים והנה אמר זה להודיע כי לולי עצת יוסף היה נעדר הלחם גם כן במצרים כמו שנעדר בכל הארצות אשר סביבותיה וזה כי ברבות הטובה ירבו האנשים יותר לאכול ממנה.
@56 **ויפתח יוסף את כל אשר בהם.** ר"ל שהוא פתח בכל ערי מצרים כל האוצרות שהיה בהם בר למכור למצרים.
@56 **וישבור למצרים.** הוא מעניין מכר או ר"ל שנתן להם שבר והוא התבואה כטעם כי יש שבר במצרים שבר רעבון בתיכם.
@57 **וכל הארץ באו מצרימה לשבור אל יוסף.** ר"ל שכל אנשי הארץ באו אל יוסף מצרים לקנות תבואה.
@58 **וירא יעקב.** ר"ל וישמע יעקב שכבר אמר אחר זה הנה שמעתי וככה וכל העם רואים את הקולות ואת הלפידים.
@58 **למה תתראו.** יתכן שהיו מתקוטטים יחד בסבת הטרף שהיה כל אחד מהם רוצה לקחת ממנו לזון בניו כשהיו מבקשים לחם והאחרים היו מונעים ממנו כמשפט בשני רעבון ויהיה תתראו מענין נתראה פנים כמו שפירש החכם אבן עזרא או יהיה הרצון בזה והוא הנכון בעיני. למה תשוטטו בארץ כנען לבקש שבר רעבון בתינו מהסוחרי' אשר שם ותתראו מפני אנשי כנען הלא לכם לירא פן יקחו המקומות אשר סביב שכם נקמת שכם מכם. אל תתראו בארץ הזאת לשוטט בה אך רדו מצרי' לשבר בר כי שמעתי כי יש שבר במצרים והעד על זה הפירוש מה שאמר ושברו לנו משם ר"ל שלא תשברו לנו מארץ כנען וזה יהיה סבה אל שנחיה ולא יהיה לנו לירא שימיתונו אנשי כנען בסבת שכם כי לא תתראו להם.
@65 **ויכר יוסף את אחיו והם לא הכירוהו.** לפי שהיה קטון בהפרדו מהם ובלא זקן והם היו גדולים והיה להם זקן כמו שאמרו ז"ל.
@66 **ערות הארץ.** סודות הארץ וסתריה כמשפט המרגלים שיחקרו באי זה אופן הארץ נשמרת ומאי זה מקום יתכן שיכנסו בה.
@68 **כלנו בני איש אחד נחנו.** קבלתי בפירוש זה הפסוק מהרב א"א נ"ע כי זה אמרו לאמת שאינם מרגלים לפי שהמרגלים הולכים בסכנה עצומה כפשע בינם ובין המות ואין מדרך האדם שישים עשרה מבניו בסכנה הזאת וזה שהוא אולי יקל באחד מבניו או בשנים אך לא במספר רב כזה. ולזה אמתו לו מזה שהם כנים ר"ל שהן אנשי אמת לא מרגלים. וידמה לפי זה הפירוש שהוא אמר להם כי אין זאת ראיה שהם אינם מרגלים כי אולי נשארו לאביהם בנים רבים ולזה הקל בהם והם השיבו כי לא נשאר לאביהם כי אם אחיהם הקטן והוא הוסיף לענותם שזה ראיה שהם מרגלים שאם היו באים לשבור אוכל היו באים כלם אך השאיר אביהם אחיהם הקטן שלא לסכן כל בניו והבחינה האמיתית תהיה בזה שהם יאסרו כלם מלבד אחד ילך לקחת אחיהם הקטן ואם לא ירצה אביהם לשלח אותו הנה זה ראיה כי הוא הקל בשאר בניו והשאיר לו הקטן לרוב אהבתו אותו שאם היה אוהב אותם במדרגת הקטן היה שולח הקטן תכף ואם לא ישלח הקטן הזה הוא ראיה כי לא ישלח שאר בניו להיותו מיקל בהם.
@74 **משמר.** בית האסורים או אסרם בבית אחד מביתו.
@76 **שבר רעבון בתיכם.** כתרגומו.
@80 **כי שומע יוסף.** מבין.
@80 **כי המליץ בינותם.** לפי שכאשר היו מדברים עם יוסף היה ביניהם מליץ ולזה חשבו שלא יהיה יוסף מבין לשון עברי.
@84 **בפי אמתחתו.** הו' שקו אבל נקרא אמתחת לפי שהוא נמתח כשממלאין אותו.
@85 **ויצא לבם.** כאלו יצא לבם מהם מרוב הפחד והדאגה.
@86 **ויגדו לו את כל הקורות אותם.** לא היה צריך לספר מה אומרו לו אבל הם העלימו ממנו קצת ולזה שב לספר מה שהגידו לו וזה שהם העלימו ממנו האסרם כלם והאספם על משמר שלשת ימים והעלימו ממנו האסר שמעון. ואולם עשו זה כדי שיתרצה יעקב יותר לשלוח בנימן וזה שאם היה אדוני הארץ אכזרי מאד בעיני יעקב ומבקש תואנות לא היה מתרצה בשום פנים לשלחו שם.
@93 **יוסף איננו ושמעון איננו.** זאת ראיה שלא נתברר בלב יעקב שהיה יוסף מת אבל הענין בספק אצלו ולזה לא אמר יוסף מת ושמעון איננו ואמר אחר זה ואחיו מת כמשפט הנבוך שפעם היה חושב שיהיה מת ופעם היה חושב שאיננו מת.
@94 **שני בני תמית.** הנה אמ' בזה ראובן דבר שגעון ולזה לא השיבו יעקב על דבריו דבר ואמנם כפר זה להורות כי ראובן לא היה חכם ולזה נתגאל במשגל המגונה אשר זכרה התורה והוא שכבר שכב את בלהה פילגש אביו כי החכם לא יפותה לבו לכמו אלו והפעולו' המגונות.
@95 **והורדתם את שבתי ביגון שאולה.** ר"ל כי עתה שגדל בנימן היה מתנחם בו קצת נחמה מעניין יוסף ואלו ימו' בדרך אשר ילכו בו לא יסור אבל יעקב עד יום מותו כי לא ישאר לו מרחל דבר יתנחם בו.
@97 **כאשר כלו.** כאשר השלימו.
@98 **העד העיד.** הוא מענין התראה לאמד העוד אביכם חי היש לכם אח יתכ' שכבר שאל להם יוסף זה ואם לא נזכר והעד מה שאמר לו יהודה אדוני שאל את עבדיו לאמר היש לכם אב או אח ואחשב שכאשר אמרו לו כלנו בני איש אחד נחנו שאל להם יוסף אם יש עוד להם אח ואם אביהם חי כי בזה תלקח ראיה אם הם מרגלים או כנים וזה שאם לא היה להם אב לא תהיה ראיה שיהיו בנים היותם כלם בני איש אחד וכן אם היו לו אחים רבים כמו שביארנו במה שקדם והודיעוהו בתשובתם שני אלו העניינים יחד גם יתכן שהגידו לו אחר זה שאביהן זקן ושאחיהם הנשאר הוא ילד זקונים כמו שיראה ממה שאמ' יהודה ליוסף במה שיבא אחר זה וכן יראה ממנו כי אחר זה אמר להם יוסף שיורידו אחיהם הקטן אליו וישים עינו עליו והשם השיבו כי לא יוכל הנער לעזוב את אביו ועזב את אביו ומת ואחר כן אמר להם יוסף כי זה יורה על היותם מרגלים ואספם אל משמר שלשת ימים ואמנם קצרה התורה בזה הספור.
@103 **ונחיה ולא נמות.** הוא על דרך הצחות ובלשון נהוג מאד בלשון הערב או יהיה הרצון בזה שאם נשוט לקנות שבר בארץ כנע אולי נמות כלנו ואתה וטפינו על ידי בני כנען לקחת נקמת שכם ממנו. ואם נלך למצרים לא יהיו בסכנה כי אם ההולכים.
@106 **מזמרת הארץ.** מן הדברים היותר משובחים שימצאו בארץ כנען.
@107 **וכסף משנה.** הוא כמו משנה שכשר שכיר והרצון בו שיקחו ממנו כפל ממה שלקחו בראשונה כי אולי נתיקר. או יהיה פירוש משנה כסף כסף שני כטעם מגיד המשנה. והנה בלי ספק היה ידוע להם השער כי אנשי העיר ההיא היו הולכים תמיד לארץ מצרים לשבור אכל והיו מודיעים להם השער. כאשר שכלתי שכלתי כאשר שכלתי מיוסף ואירא ששכלתי מכלכם. עד בואכם. כי יעקב היה ירא שיעלילם האיש.
@111 **בצהרים.** הוא העת שהשמה נראה בו בחצי השמים והוא מעט קודם חצי היום עד מעט אחר חצי היום. ולזה נקרא בלשון מורה על שנים כי קצתו מזוהר הבקר וקצתו מזוהר הערב והאנשים יחשבו בכל זה הזמן שיהיה השמש בחצי השמים למיעוט התחלפות גובה השמש בזה העת כמו שהתבאר בחכמת הכוכבים.
@113 **על דבר הכסף השב באמתחותינו להתגולל עלינו.** כדי שהתגולל עלינו עלילת הכסף לומר שאנחנו גנבנוהו. וכן ולהתנפל עלינו כאלו אמר שתפול עלינו זאת העלילה או הרצון בו להדיח עלינו הרעה ולהפילה עלינו בדרך שיקחו אותנו לעבדים ויקחו חמורינו. ואולם אמרו זה כי אולי היה מפורסם להם כי זה העונש הוא כמו זאת הגנבה במצרים והעד על זה מהו שאמר אחר זה אשר ימצא אתו יהיה לי עבד.
@118 **נתן לכם מטמון.** כמו שפירש החכם אבן עזרא כי זה הבר היה מקובץ מאנשים רבים ויתכן שהיה לאחד מהם מטמון בבר אשר לקח ממנו יוסף ולזה לא זכה בו המלך והוא למי שהגיע אליו בגורלו וכן יתבאר הדין הזה בשני ממציעא.
@120 **ויכינו את המנחה.** שמוה בכלים נאים וסדרוה באופן היותר שלם שיוכלו.
@123 **ויקדו וישתחוו.** הכניעו קדקדם בהשפלתם ראשם לכבודו כמשפט ואח"כ נכנעו יותר והשתחוו.
@125 **נכמרו.** נתחממו. כמו עודנו כתנור נכמרו.
@126 **ויתאפק.** ויתחזק מההפעלו' שהתפעל בראיית אחיו.
@128 **וישבו לפניו הבכור כבכורותו.** הנה יתכן שיוסף צוה להם שישבו בזה הסדור ולזה תמהו איך קרה שיהיה זה הסדור לפי הסדור שיש להם בבכורה ובצעירות.
@129 **משאות.** מנות. והנה נתן משאת אחד לשנים במשפט ולבנימן שהיה יחיד נתן משאה יותר גדולה מהמשאה שנתן לשנים אחיו. ולזה יהיה פירוש הפסוק ותרב משאת בנימן ממשאת כולם חמש ידו' שכבר רבה משאת בנימן ממשאת שתהיה לאחיו שהיו להם חמשה חלקים לכל שנים מהם חלק אחד כי הוא רחוק שישים לבנימן לבדו משאה יהיה שעורה כמו חמשה משאר המשאות.
@129 **וישכרו.** ר"ל ששתו עמו הרבה.
@132 **והאנשים שלחו.** נתן להם רשות ללכת.
@134 **נחש ינחש בו.** הוא מענין נסיון בטעם נחשתי ויברכני יי' בגלליך. והרצון בזה כי זה הגביע הוא אשר ישתה אדני בו ולזה לא יתכן שישכחהו אבל יראה שהו' מעלים עיניו כשיקחוהו לנסות את האנשים אשר יבואו לפניו הם אנשי אמת או אנשי און ומרמה וזה שאם יקחוהו יתבאר לו שהם אנשים גנבים ויצוו לשמור הבית בבואם שם ואם לא יקחוהו יתבאר לו שהם אנשי אמת אחר שהגביע לפניהם ויוסף מעלים עיניו ממנו ולזה אמר יוסף הלא ידעתם כי נחש ינחש איש אשר כמוני ר"ל שאיש כמוהו שהיו באים לביתו רבים אשר אינו מכירם הוא מנסה את האנשים הבאים לביתו אם הם נאמנים אם לא ויצוה לשמור ביתו מהם.
@138 **אשר ימצא אתו מעבדיך ומת.** התירו עצמם לעונש נוסף על העונש הראוי על זה להורות שהם לא גנבו הגביע.
@139 **ויאמר גם עתה כדבריכם כן הוא** וקבלתי מזה פירוש מהרב אדוני אבי נ"ע שהוא אמר להם גם עתה שאני חושד אחד מכם כדבריכם כן הוא. שבכלל אתם אנשי אמת ולזה אם אמצא הגנבה ביד איש אחד מכם לא אחשוד אתכם שתהיה נגנבת בהסכמת כולכם. ולזה לא יהיה נענש כי אם מי שתמצא בידו הגנבה והוא פירוש נאה מאד.
@142 **ויעמוס.** ויטעון.
@143 **ויבא יהודה ואחיו.** לפי שהיה יהודה לבדו משתדל בהצלת אחיו כי הוא ערב אותו זכרו בביאור.
@145 **מה נדבר ומה נצטדק.** הנה אין לנו פה להתנצל אך באמת תדע כי אין לנו חטא בזה אך הוא סבב ה' יתע' שיקרה לנו דבר יחשב לו עון ואולם הושם הגביע בזולת כוונה על יד ממלא השקים באמתחת בנימן אך באמת לא גנבו. והנה יחס מה שיתחדש על דרך הקרי ליי' יתעלה כי כמו אלו הדברים אשר בקרי ייוחסו לו כמו שזכר הרב המורה וזכרו גם כן הפילוסוף בשני מהשמע.

@1 **ויהי מקץ שנתים ימים וגומ' עד ויוסף בן שלשים שנה:**
@1 והנה דברי זה הספור מבוארים:
@1 והנה התועלות המגיעות מזה הם שמונה:
@1 **התועלת** הראשון הוא במדות. והוא להודיע שראוי לאדם בבאו לפני הגדולים שיקשט עצמו בבגדיו ובענייניו האחרים לפי מה שאפשר כי בזה מההדור לגדולים ובזה גם כן יהיו דבריו יותר נשמעים. ולזה תמצא שגלח יוסף והחליף שמלותיו בבאו לפני המלך. ולזאת הסבה היו החסידים הגדולים מתקשטים כשהיו מתפללים לשם יתעלה לכבודו אמרו ז"ל זה אלי ואנוהו:
@1 **התועלת** השני הוא במדות. והוא שראוי לאד' כשידבר עם הגדולים שיהיו דברים מעטים. ולזה תמצא שענה יוסף לפרעה זה המאמר הנפלא אשר כלל מהשלמות הרבה במלות מועטות והוא מה שאמר לו בלעדי אלהים יענה את שלום פרעה. והנה בפתרונו החלומות בא מאמרו ג"כ בתכלית הקצור והתקון ומבואר מדבריו שם:
@1 **התועלת** השלישי הוא במדות. והוא שראוי לאדם כשיוכרח לדבר לפני המלכים והשרים ולא ידע אם יהיה בדבריו מה שיקשה להם שיקדים להתנצל בזה פן יקרהו נזק מכעסם עליו. ולזה תראה כי מפני שלא ידע יוסף מה יהיה פתרון החלומות ואם יהיה בו דבר נגד פרעה הקדים התנצלותו בזה והראה שמה שיענה מזה הוא מה שיראהו השם יתע' ולזה לא יהיה בבחירתו לפתור לפי מה שירצה והיה בזה מחלק הדברים מפיוס לב פרעה מה שלא יעלם וזה שהוא התפלל לשם יתע' שיענה שלום פרעה:
@1 **התועלת** הרביעי הוא במדות. והוא שראוי לאדם כשישאלוהו המלכים והגדולים בהודעת דבר מה שלא יעלים מדרגת ידיעתו בדבר ההוא כי בזה תהיה תשובתו יותר מקובלת. והמשך כי המהנדס אם ישאלוהו מענין ההנדסה אין ראוי שיאמ' שאינו יודע בהנדסה אבל יאמר שהוא עיין בחכמה ההיא והנרא' לו מהעיון ההוא הוא מה שישיב להם כי בזה תתפייס יותר נפשם בתשובתו. הלא תראה שיוסף כששאלוהו מפתרון החלום הראה בדבריו כי רוח אלהים בו והוא יגלה לו פתרון החלומות ולזה אמר בלעדי אלהים יענה את שלום פרעה והיה זה סבה אל שיאמר אליו פרעה הנמצא כזה איש אשר רוח אלהים בו:
@1 **התועלת** החמישי הוא בדעות. והוא להודיע שאין בבחירת הפותר לפתור לטוב או לרע ולא יועיל פתרונו בזה אבל הפתרון יהיה לפי המוסכם עליו מהשם יתע' ומי שיפתר החלום בזולת האופן ההוא לא יהיה פתרונו פתרון. ולזה אמר יוסף בלעדי אלהים יענה את שלום פרעה. להודיע שאין הפתרון מסור בבחירתו אבל הוא מוגבל מהשם יתע' שהוא יודע כל העתידות:
@1 **התועלת** הששי הוא בדעות. והוא שהשנו' החלום מורה על אמתתו ומהירו' באו והסב' בזה היא שהש"י ישפיע לאדם החלומות הצודקים באמצעות המחשבות השופעות מהגרמים השמימיי כמו שביארנו בשני מספר מלחמות יי'. ושם ביארנו כי לזאת הסבה יתכן שימצא הכזב הרבה בחלום ובקסם לפי שזאת ההשפעה לא תהיה כי אם משליטים ולה יעלם ממנו מה שיושפע מהבלתי שליטים וביארנו שם ג"כ כי כבר יקרה לאדם שיחלום בהקיץ חלום צודק ושכבר ימצא סגולת זה החלום שהוא יגיע תכף והיה זה כן לפי שהשליט בזאת ההשפעה הוא בעינו השליט בזה המקרה בחדושו. ולה יקרה לו מפני חוזק שלטנותו בהשפעה שיספיק לו להשפיע לאדם מעט מן ההתבודדו' לקבל זה השפע וכן עניין בזה בעינו בהשנו' החלום מורה על חוזק ההשפעה וזה ממה שיורה שזה המקרה מסודר מהשליט בהשפעה ולזה יחוייב שיגיע זה המקרה תכף וזה כלו מבואר למי שהתבונן בדברינו בשני מספר מלחמות השם:
@1 **התועלת** השביעי הוא במדות. והוא שראוי לאדם להשתדל בהשגת החכמה כפי היכול' כי היא תושיבהו בין נגידים ותסבב שיהיה לו עושר וכבוד. הלא תראה כי יוסף הצדיק עלה לזאת המעלה מפני יתרון חכמתו עד כי מבית האסורים יצא למלוך:
@1 **התועלת** השמיני הוא במדות. והוא שאין ראוי לאדם שישתדל לבטל מה שנגזר מהשם יתע' בכמו זה האופן אשר השתדלו לבטלו אחי יוסף כשמכרוהו כי הם חשבו שהוא רחוק שיהיה מושל עליהם אחר שהרחיקוהו מעליהם ועם היותו נמכר לעבד וזה היה כלי אל שהגיע יוסף לתכלית הממשלה והשררה וכזה יקרה הרבה במי שישתדל לבטל גזרות השם יתע' בזה האופן כמו שסופר לנו מרימולוס ורומילוס שחלם אביהם בליל לידתם ששני אודים יצאו מנחיריו ישרפו עיר ממשלתו וכאשר הקיץ הודיעוהו שכבר ילדה אשתו תאומים ושפט שהם האודים אשר חלם וצוה להשליכם היערה ולהמיתם שם ונזדמנה להם שם דובה והניקה אותם כמו שאמרו במדרש תלים וכאשר גדלו החריבו עיר אביהם ובנו רומי ומהם המשפחות הגדולות מרומי והם הדוכיים. ואולם האופן שיתכן שיבטל האדם גזירת השם יתעל' הוא שאם היה נכון לבא רע עליו הוא שידבק בשם יתע' לפי היכולת והוא ישגיח בו ויצילהו ממנו או יברח מהמקום ההוא אשר בו היה נכון לו לבוא רע. וראוי שלא יעלם ממנו שיוסף לא שם בשר זרועו במה שאמר לשר המשקים אך ראה כי מזכירתו אותו לפרעה יגיע לו טוב כמו שהיה העניין בסוף וסבב השם יתע' אשר לו נתכנו עלילות שלא זכרו שר המשקים לפרעה עד בא העת אשר היה יותר נכון ליוסף. והנה תמצא כי כל התלאות אשר מצאוהו מעת המכרו כלם היו לו אל שיגיע לזאת הממשלה וזה מבואר במעט עיון:
@46 **ויוסף בן שלשים שנה עד סוף הפרשה:**
@46 והנה דברי זה הספור מבוארים מאד עם מה שקדם לנו מדברים. ואולם התעלות המגיעות מזה הספור הם עשרים:
@46 **התועלת** הראשון הוא במדות. והוא שראוי לאדם בעשותו פועל אחד שיעשהו באופן יאות אל המקבלים ואעפ"י שהוא שליט בפועל ההוא כי בזה יתפייס לבבם ויפותו יותר לעשות רצונו. הלא תראה כי יוסף ברצותו לאסוף כל הבר שיוכל בארץ מצרים בשני השובע עשה זה בתחבולות יתפייס בהם לב האנשים וזה שהוא שם כל תבואות העיר בתוך העיר ההיא באופן שהיו מתפייסים בזה אנשי העיר לחשבם ששם תמצא להם זאת התבואה בעת הצורך ולא ימות ברעב עם שהם היו אוהבים יותר תבואת העיר ההיא מתבואת עיר אחרת:
@46 **התועלת** השני הוא במדות. ומשפטי התורה והוא שאין ראוי לאדם להמשך אחר ההנאו' בעת שהיות שכניו בצער. ולזה תמצא שספרה התורה שיולדו ליוסף שני בנים בטרם תבא שנת הרעב להורות כי בשנת הרעב לא שמש מטתו ומזה המקום למדו רז"ל שאסור לשמש מטתו בשנת רעבון. ואמרו עם זה שחשובי בנים משמשין מטותיהם בשנת רעבון וזה גם כן אפשר שילמד מזה הפסוק וזה כי אם לא יהיו לו בנים קודם בא הרעב אולי לא היה נמנע מלשמש מטתו בשני רעבון כי ראוי לאדם להשתדל לקיים המין:
@46 **התועלת** השלישי הוא בדעות. והוא להודיע שכל הטובות השופעות בזה העולם הם שופעות מהשם יתע' ולזה יחס יוסף כל הטובות השופעות לו לש' ית' ומפני זה אומר בקריאת השמות לבניו נשני אלהים כי הפרני אלהים:
@46 **התועלת** הרביעית הוא במדות. והוא שראוי לאדם שיברח ממה שיש בו חשש סכנה ואפי' באפשר רחוק ולזה מנע יעקב בניו מהתראות בארץ כנען לשוט בה לקנות בה תבואה ואעפ"י שכבר היו מוצאים אותו שם קרוב להם ובחר שילכו בארץ מצרים לקנות ואעפ"י שהדרך רחוק פן יכירום אנשי כנען וימיתום על דבר שכם:
@46 **התועלת** החמישי הוא במדות. והוא שכאשר קרה לשני' מבית אחד או מחבורה אחת מקרה מה בדבר מה ראוי שיתרחק השלישי מהדבר ההוא פן יקרהו נזק בכמו המקרה ההוא. וזה כי מפני שמתה רחל בדרך ובנה יוסף גם כן לפי מחשבתו הנה ירא יעקב שימות בנימן בדרך אם ישלחהו שם:
@46 **התועלת** הששי הוא במדות. והוא שראוי למי שהוא נכון שיגיעו אליו רעות שימעט בעסקיו ויעמוד בביתו עד יעבור זעם כי בזה אולי ינצל מהרעות. ואולם בהרבות עסקיו ולכתו בדרך הוא כמו מבקש הרעות ומתנועע אליהם ולזה ירא יעקב שיקרה לבנימן אסון בדרך אבל בבית לא היה צריך להיות ירא מזה:
@46 **התועלת** השביעי הוא במדות. והוא שאין ראוי שיקל האדם בשמירת מה שהפקר לו ויעזוב ההנהגה והשמירה ההיא לזולתו מפני עוצם מדרגתו שנתן לו המפקיד בשולטנות ובשררה כי כבר יגמלהו רע תחת טוב אבל ראוי שיפליג בשמירת הדבר ההוא כי מה שאפשר כי בזה מהיושר ומגמילות טוב למי שגמלהו טוב מה שלא יעלם. ולזה תמצא שיוסף עם היותו שליט בכל הארץ היה הוא בעצמו משביר לכל עם הארץ בדרך שישלם לו שמירתו באופן היותר שלם שיהיה אפשר ולא מנעתהו שררתו ושולטנותו מהשגיח בזה:
@46 **התועלת** השמיני הוא במדות. והוא שאין ראוי לשלם שיגמול רע למי שגמלהו רע בהיות לאל ידו לעשות ולזה תמצא שבנפול אחי יוסף לפניו ובידו, לא שלם להם רעה תחת הרע אשר גמלוהו אבל השגיח בהם וכלכל אותם כמו שיבאר אחר זה ואמנם הכאיב לבם מעט בראשית העניין כדי שתשלם לו הידיעה בשלום אביו ואחיו בנימן ויתבאר לו איך מנהגם עם אחיו בנימן שאם היו שונאים אותו ומתנכלים להמיתו כמו שנהגו עמו היה לוקח בזה עצה להפרידו מהם ולהצילו מידם וזה שאם לא היה לו חושד אותם כמרגלים או בדבר מהדברים הרעים והמגונים לא היה לו דרך לחקור שיש להם אב או אח כי לא היו מבקשים להתחתן עמו וכאשר ידע שאחיו חי השתדל על כל פנים שיביאוהו אליו והכביד ענינם בתחלה ותקל בסוף ואמר להם שהשם הוא ירא כי בזה היה להם מהפיוס והסרת הפחד מה שלא יעלם וזה גם כן יהיה סבה שלא יכאב לב יעקב מאד אם ישלח בנימן מצרים כי כבר נתפרסם לו שאדני הארץ הוא ירא אלהים והנה אסר שמעון לפניהם כדי שיוכרחו להביא בנימן אליו וזה שאם יהרגוהו בדרך לשנאתם אותו ישאר שמעון כל ימיו תחת יד יוסף אסור ולא יהיה לו דרך לברוח משם ולזה הוציא שמעון ממאסרו תכף שבא בנימן והכניסם כולם בביתו לאכול לחם עמו לפייס לבם יותר וכדי שיוכל להעליל בנימן מגביע הכסף והראה להם עם זה רב חמלתו על בנימן וחנינתו אותו כשבירך אותו ורבה משאתו ממשאת כלם לפייס לבם שלא יחרדו מאד כשיעלילום מזאת הגנבה להשענם כי השליט על הארץ הוא איש חסד ושהם נקיים מזה ולולי זה כבר היה לו לירוא שמא ימיתו עצמם כשתתגלגל עליהם זאת העלילה מרוב הדאגה והבושת והפסד והנה השתדל יוסף להעליל אחיו בנימין לבחון איך היה מנהג אחיו עמו ר"ל אם הם שונאים אותו ויעזבוהו וילכו או אם יאהבוהו וישתדלו בהצלתו כפי היכולת ולזה תמצא שכאשר נתברר לו שאחיו הם נוהגים עם בנימן כמנהג האחים אז גלה להם שהוא יוסף והשתדל שיבואו אליו וכלכלם כדי שלא יורשו:
@46 **התועלת** התשיעי הוא בדעות. והוא להודיע שהשם יתע' יענש הטובים על מה שיעשוהו מהפעולות המגונות ולזה תמצא שכבר יחסו בני יעקב הצרה הבאה עליהם על מה שחטאו בעניין יוסף:
@46 **התועלת** הי' הוא במדות. והוא שראוי לאדם שיצדיק עליו את הדין בבא עליו הרעה ויפשפש במעשיו וייחס אותה לרע מעשיו ולא יתרעם מה' יתע' בהביאו עליו מה שיבוא מן הרע. ולזה תמצא שייחסו בני יעקב מה שפגשם מהרע לרע מעשיהם בענין יוסף:
@46 **התועלת** הי"א הוא במדות. והוא שראוי לשלם שיתפעל בראותו אחיו בצרה ואף אם גמלוהו רע בתכלית מה שאפשר. הלא תראה כי יוסף בראותו אחיו בצרה נכמרו רחמו עליהם ויסוב מעליה' לבכות ואמנם הוכרח להשאיר' בכאב לב מעט כדי לבחון מה שרצה לבחון אותו מבנימן:
@46 **התועלת** הי"ב להודיע יושר יוסף שלא רצה לשלוח יד בכסף הבא אליו לשלחו אל אביו לפי שכבר זכה בו פרעה ואע"פ שכבר בא כל זה הטוב לפרעה בסבתו ואמנם השיב לאביו הכסף ששלח אליו לבדו ושלח אליו מלא כליו בר וצדה לדרך לפי שכבר השליטו פרעה לעשות מהדבר ההוא כל מה שירצה ולתת למי שירצה ולמכור למי שירצה. הלא תראה שכבר אמר פרעה לבאים אליו לכו אל יוסף ואשר יאמר לכם תעשו:
@46 **התועלת** הי"ג הוא במדות. והוא שראוי לכל אדם שיתרחק מהמשגלים המגונים כי לא יתגאל בהם כי אם מי שהוא חסר דעת כאומרו נואף אשה חסר לב. ולזה בארה לנו התורה כי ראובן שנתגאל עם פלגש אביו היה חסר דעת בתכלית החסרון וזה יתברר במה שאמר את שני בני תמית כי זה המאמר היה בתכלית הפתיות וזה מבואר בנפשו. ואולם יהודה השתדל בזה בחכמה ולזה המתין שכלה השבר אשר הביאו ממצרים ואמר לאביו עם זה דברי' נכוחי' עד שנתרצה ושלחו עמו:
@46 **התועלת** הי"ד הוא במדות. והוא שראוי לאדם כשתעלה עליו חמת אחד שיכין עצמו לפייסו בדורון מהיותר משובח שימצא כי בזה יכפה אפו ולזה צוה יעקב לשלוח לאיש מנחה מזמרת הארץ והכין עצמו עם זה להתפלל לש' יתע' שיתן להם רחמים לפני האיש:
@46 **התועלת** הט"ו הוא במדות. והוא שאין ראוי למי שיחשדהו האדון בדבר רע שיפליג ברבוי המנחה כי זה ממה שיביא להאמין שהחשד הוא אמת. ולזה תמצא ביעקב שלא רצה בזה המקום ברבוי הדורון עם מה שתראה שהפליג ברבוי הדורון לעשו אבל היה מעט מה ששלח לו מכל מין מעט צרי מעט דבש נכאת ולוט בטני' ושקדים ויהיה אמרו מעט דבש מושך עצמו ואחר עמו כאלו אמר מעט דבש ומעט נכאת ומעט לוט:
@46 **התועלת** הי"ו הוא בדעות. והוא שאין ראוי לאדם כשיירא מדבר רע שישען על התפלה לשם יתע' לבד אבל ראוי שישתדל בכל הסבות שאפשר בהצלתו ויחבר אל זה התפלה לש' יתע' כי הש' יתע' כשיעזור לדבקים בו וישגיח בהם ירצה שיחברו אליו הסבות הנאותות. ולזה אמר לשמואל כשיירא שיהרגהו שאול עגלת בקר תקח בידיך ואמרת לזבוח ליי' באתי. ולזאת הסבה תמצא בזה המקום שאחר שלקח יעקב עצה לפייס האדון כפי מה שראוי התפלל לש' יתעלה שיתן להם רחמים לפני האיש ובכלל אם ישען השלם על התפלה לש' יתע' לבד יקר' בזה מההפסד מה שלא יעלם עם שכבר יביא זה למעוט האמונה בהשם יתע' כשלא יבואו לשלם ההוא מבוקשיו אשר הוא סבת העדר הגעתם כאמרם ז"ל למען יברכך יי' אלהיך יכול בטל ת"ל בכל אשר תעשה:
@46 **התועלת** הי"ז הוא במדות. והוא שראוי למי שיירא שיחשד מדבר שיקדים מה שיתבאר ממנו שאין לו פשע ואין לו חטאת על זה קודם שהשיגהו החשד שאם ימתין עד שישיגהו החשד הנה לא יועילו התנצלותו כמו שיועיל לו קודם זה. והמשל שמי שבא בידו ממון שלא כדין אם ימתין להשיבו עד שיבקשוהו ממנו הנה יחשבוהו שהוא עכבו לעצמו בכונה. אבל אם יתעורר להושיבו קודם שיבקשוהו ממנו הנה זה יורה על היותו בלי פשע על זה ולזה הקדימו אחי יוסף להודיע כי כבר חושב כספיהם בפי אמתחותיהם ושהם משיבים אותו קודם שיעוררו אותם על זה:
@46 **התועלת** הי"ח הוא במשפטים התוריים והוא מי שלקח תבואה מאנשים רבים ואחר מכר ממנה לאחר ומצא במה שהגיע לו ממנה מטמון הרי הוא שלו כי זה יורה שלא היה המטמון מהסוחר כי הוא קנה זה מאנשים רבים ואולם כשלא היה זה בזה האופן לא זכה בו זה הקונה וכבר נתבאר זה השרש בפרק ב' ממציעא:
@46 **התועלת** הי"ט הוא במדות. והוא שראוי שיושיבו האנשים במסבה לפי השנים ר"ל שגדול השנים ישב ראשון וצעיר השנים אחרון ולזה הושיבם יוסף לפניו הבכור כבכורתו והצעיר כצעירתו וכזה אמרו רז"ל במסבה הולך אחר הזקנה בישיבה אחר החכמה:
@46 **התועלת** הכ' הוא במדות. והוא שראוי לאדם לשמור ביתו כשיכנס בביתו שום אדם ויהיו בעיניו כלם כלסטים וכגנבים ואם ירבו הבאים לביתו בדרך שלא יוכל להשמר מכל אחד ואחד הנה ראוי לו שינסה מי הוא בלתי נאמן ויזהר ממנו לבד. ולזה אמר יוסף הלא ידעתם כי נחש ינחש איש אשר כמוני כמו שביארנו:
